/* ===== Grand Admiral Thrawn (42nd build) ===== */
window.OPS.thrawn = {"meta": {"word": "THRAWN", "accent": "#5fa8d3", "body": "cloth", "budget": 120, "btn": "⚙ EMPIRE", "dur": "4 weeks", "hrs": "20–40 hrs", "parts": "Uniform + makeup", "budgetRange": "€80–200", "lead": "Grand Admiral Thrawn — the blue-skinned Chiss tactician. No armour, no saber: a crisp white Imperial admiral's uniform, blue skin, glowing red eyes and an ice-cold stare. This is a makeup-and-tailoring build, not a print job.", "ruleLabel": "▌ THE ONE RULE", "rule": "Keep it SHARP. A pressed, well-fitted white uniform sells Thrawn more than any prop — sloppy fabric breaks the whole look.", "intro": "OPERATION THRAWN", "introSub": "IMPERIAL ARCHIVE · BUILD MANUAL · FILE MITTH'RAW'NURUODO", "footer": "OPERATION THRAWN · BUILD MANUAL · GRAND ADMIRAL · FREE TO SHARE", "chapLabel": "▌ CHAPTERS · 6 TOTAL", "pubPdf": "thrawn_public.pdf", "weekPdf": "thrawn_byweek.pdf", "quote": "To defeat an enemy, you must know them."}, "forge": {"skin": {"name": "Blue Skin", "type": "FACE · 01", "kind": "Makeup", "hours": 3, "cost": 25, "priority": "CRITICAL", "description": "Chiss blue on every visible area — face, ears, neck, hands. Use a blue cream or alcohol-activated makeup, then seal with setting powder and spray.", "tip": "Blue-grey, not cartoon blue — mix in a little grey so it reads as skin under light.", "files": []}, "eyes": {"name": "Red Eyes", "type": "FACE · 02", "kind": "Buy", "hours": 1, "cost": 30, "priority": "CRITICAL", "description": "Glowing red contact lenses — the single most recognisable Thrawn feature.", "tip": "Buy from a reputable seller, follow wear-time limits, never sleep in them.", "files": []}, "hair": {"name": "Black Hair", "type": "HEAD · 03", "kind": "Style / Wig", "hours": 1, "cost": 20, "priority": "HIGH", "description": "Slicked-back jet-black hair (wig if needed). Sharp part, not a strand out of place.", "tip": "Gel or a wig — Thrawn's hair is always immaculate.", "files": []}, "tunic": {"name": "White Admiral Tunic", "type": "BODY · 04", "kind": "Buy / Tailor", "hours": 6, "cost": 60, "priority": "CRITICAL", "description": "The white double-breasted Grand Admiral tunic with the high collar. Start from a white naval/officer tunic and tailor it crisp.", "tip": "Get it fitted — a baggy tunic ruins the whole silhouette.", "files": []}, "rank": {"name": "Rank Plaque + Collar Insignia + Code Cylinders", "type": "CHEST · 05", "kind": "Print / Buy", "hours": 3, "cost": 25, "priority": "HIGH", "description": "The 12-tile chest rank plaque (top row 3 blue + 3 yellow/gold, bottom row 3 blue + 3 red), the metallic-silver collar insignia (a bar plus an outward-facing triangle on BOTH sides of the high collar), and the silver code cylinders in the chest pockets.", "tip": "This is the detail people check — get the 12-tile plaque colours right and don't forget the silver bar-and-triangle on each collar.", "files": []}, "legs": {"name": "White Trousers + Boots", "type": "LEGS · 06", "kind": "Buy", "hours": 2, "cost": 35, "priority": "MEDIUM", "description": "White uniform trousers and tall black boots, crisp crease.", "tip": "Bright white, sharp line down the leg.", "files": []}, "gloves": {"name": "Black Gloves", "type": "HANDS · 07", "kind": "Buy", "hours": 1, "cost": 10, "priority": "LOW", "description": "Black leather gloves. If you go gloveless, the hands and wrists need blue makeup too.", "tip": "Optional — Thrawn is often gloved.", "files": []}, "goldepaulettes": {"name": "Gold Epaulettes", "type": "BODY · 08", "kind": "Buy / Craft", "hours": 3, "cost": 15, "priority": "HIGH", "description": "The signature gold shoulder boards on each shoulder of the white Grand Admiral tunic — a silhouette-defining feature. Buy a ready-made pair or build from craft foam and gold fabric/braid.", "tip": "Gold, not brass-orange — they sit flat on the shoulder and frame the whole uniform.", "files": []}, "blackbeltidentityd": {"name": "Black Belt + Identity-Disk Buckle", "type": "BODY · 09", "kind": "Buy", "hours": 1, "cost": 10, "priority": "MEDIUM", "description": "Black leather belt worn at the waist with a round metal buckle bearing the central Imperial identity/code disk — a standard part of the on-screen Grand Admiral kit.", "tip": "Plain black leather, sharp and snug — the round disk buckle is the giveaway detail.", "files": []}}, "weeks": [{"label": "Week 4", "task": "Source the white tunic, trousers and boots; order red contacts and blue makeup"}, {"label": "Week 3", "task": "Tailor the tunic; make or print the rank plaque and code cylinders"}, {"label": "Week 2", "task": "Practise the blue-skin makeup — test colour, sealing and photos under light"}, {"label": "Week 1", "task": "Full dress rehearsal, contact-lens fit check, posture and that cold expression"}], "files": [{"name": "Imperial code cylinder STL", "designer": "search Thingiverse / Cults3D", "url": "https://www.thingiverse.com/search?q=imperial+code+cylinder"}, {"name": "Grand Admiral rank insignia reference", "designer": "Imperial uniform guides", "url": "https://www.google.com/search?q=grand+admiral+thrawn+rank+insignia+chart"}, {"name": "Grand Admiral uniform (base garment)", "designer": "Etsy / cosplay tailors", "url": "https://www.etsy.com/search?q=grand+admiral+thrawn+uniform"}], "checklist": {"print": [{"name": "Code cylinders (×2–6)", "detail": "Silver, sit in the chest pockets."}, {"name": "Rank plaque", "detail": "The blue/red rank bar — print flat and paint, or buy."}], "buy": [{"name": "White admiral tunic", "detail": "Double-breasted, high collar — base to tailor."}, {"name": "White trousers + black boots", "detail": "Crisp white, tall boots."}, {"name": "Red contact lenses", "detail": "Reputable seller; mind wear-time."}, {"name": "Blue skin makeup + setting spray", "detail": "Cream or alcohol-activated, sealed."}, {"name": "Black wig or strong gel", "detail": "Slicked-back, sharp part."}, {"name": "Black gloves", "detail": "Optional."}]}, "chapters": [{"num": "01", "title": "Mission Brief", "body": "<p class='lead'>This builds <span class='accent'>Grand Admiral Thrawn</span> — the blue-skinned Chiss strategist of the Empire.</p><p>It is the rare Star Wars build with <b>no armour and no lightsaber</b>. It lives or dies on three things: a <span class='accent'>sharp white uniform</span>, <span class='accent'>blue skin</span>, and <span class='accent'>glowing red eyes</span>. Nail those and you are unmistakable across a room.</p><div class='reader-callout'><div class='label'>▌ WHY IT'S A GREAT FIRST BUILD</div><p>No printer required, low cost, and it photographs beautifully. The hardest part is makeup discipline — not engineering.</p></div>"}, {"num": "02", "title": "The White Uniform", "body": "<p class='lead'>The uniform is 80% of the read. Get it crisp.</p><p>Start from a <b>white double-breasted officer/naval tunic</b> with a high collar and tailor it to fit. Thrawn's line is clean and severe — no bagginess, no wrinkles.</p><ul><li>White tunic, high collar, double-breasted</li><li>White trousers with a sharp crease</li><li>Tall black boots</li><li>Black gloves (optional)</li></ul><div class='reader-callout'><div class='label'>⚠ FIT IS EVERYTHING</div><p>A $40 tunic that's <b>tailored</b> beats a $120 one that's loose. Press it before every wear.</p></div>"}, {"num": "03", "title": "Blue Skin & Red Eyes", "body": "<p class='lead'>The Chiss look: blue skin everywhere visible, red eyes glowing.</p><h3>Blue Skin</h3><p>Cover <b>face, ears, neck and hands</b> with a blue makeup — cream or alcohol-activated. Blend a little grey in so it reads as <span class='accent'>blue-grey skin</span>, not paint. Set with translucent powder, then a setting spray so it survives the day.</p><h3>Red Eyes</h3><p>Red contact lenses are the iconic finishing touch. Buy from a reputable lens seller, follow the wear-time limits, and never sleep in them.</p><div class='reader-table'><div class='reader-table-row'><span class='col-key'>SKIN</span><span class='col-val'>Blue cream/airbrush + grey, sealed with spray</span></div><div class='reader-table-row'><span class='col-key'>EYES</span><span class='col-val'>Red contacts — reputable seller only</span></div><div class='reader-table-row'><span class='col-key'>HAIR</span><span class='col-val'>Slicked-back jet black, sharp part</span></div></div>"}, {"num": "04", "title": "Rank, Cylinders & Details", "body": "<p class='lead'>The little details are what fans check.</p><p>Thrawn wears a <b>Grand Admiral rank plaque</b> on the chest and <b>silver code cylinders</b> in the chest pockets. Print the cylinders or buy them; print-and-paint the rank bar or source a pin.</p><ul><li>Rank plaque — get the blue/red bar layout right</li><li>Code cylinders — silver, 2–6 of them</li><li>Clean white collar, no stray threads</li></ul><div class='reader-callout'><div class='label'>▌ ACCURACY TIP</div><p>Reference the Grand Admiral insignia chart — the colour order on the rank bar is a giveaway if it's wrong.</p></div>"}, {"num": "05", "title": "Finishing & Fit", "body": "<p class='lead'>Pull it together and pressure-test it.</p><ul><li>Press the whole uniform — every seam</li><li>Do a full makeup run and photograph it under different light</li><li>Check the contacts are comfortable for a few hours</li><li>Practise the posture: still, upright, hands behind the back</li></ul><p>Thrawn is about <span class='accent'>control</span>. Stillness and a level stare sell the character more than any prop.</p>"}, {"num": "06", "title": "Game Day", "body": "<p class='lead'>How to actually <i>be</i> Thrawn when someone walks up.</p><div class='reader-callout'><div class='label'>● ●  IN-CHARACTER LINES</div><ul><li>“To defeat an enemy, you must know them.”</li><li>“I see no value in a contest of strength.”</li><li>“Your tactics are… predictable.”</li></ul></div><p>Keep it calm and measured. Thrawn never raises his voice — the menace is in the quiet.</p><div class='reader-callout'><div class='label'>⚠ LENS & MAKEUP CARE</div><p>Carry lens solution and a small makeup kit for touch-ups. Take the contacts out on the wear-time schedule.</p></div><div class=\"reader-callout\"><div class=\"label\">● ●  MORE GAME DAY LINES</div><ul><li>&ldquo;But it was so artistically done.&rdquo; <i>&mdash; his legendary line from the Heir to the Empire novel — almost admiring</i></li><li>&ldquo;They'll be the architects of their own destruction.&rdquo; <i>&mdash; from Rebels — say it quietly, like the battle is already won</i></li><li>&ldquo;Long live the Empire.&rdquo; <i>&mdash; from the Ahsoka finale — calm and polite, that's what makes it scary</i></li></ul></div><div class=\"reader-callout\"><div class=\"label\">😄 FOR LAUGHS — KID EDITION</div><ul><li>I have studied the art on your refrigerator. I now know your every move.</li><li>Your lunch trade was predictable. I foresaw the pudding swap three days ago.</li><li>My homework is late. But it was so artistically done.</li></ul></div>"}]};


/* ===== Cal Kestis ===== */
window.OPS.cal = {"meta": {"word": "CAL", "accent": "#e07b3e", "body": "cloth", "budget": 120, "btn": "✦ JEDI", "dur": "4 weeks", "hrs": "10–22 hrs", "parts": "Poncho + wraps + BD-1", "budgetRange": "€70–230", "lead": "Padawan survivor turned Jedi Knight, two eras: the Fallen Order poncho or the Survivor jacket. A layered cloth build with arm wraps, a scarf, BD-1 on your back and a dual-phase blue saber. The most beginner-friendly Jedi on the roster — almost no printing required.", "ruleLabel": "▌ THE ONE RULE", "rule": "Cal is the layers and the silhouette — a poncho or jacket over a henley, arm wraps, BD-1 riding your back. Nail the layered shape and the ginger hair; the saber and droid are the finishing flourish.", "intro": "OPERATION CAL", "introSub": "JEDI ARCHIVE · BUILD MANUAL · FILE BD-1", "footer": "OPERATION CAL · JEDI BUILD MANUAL · THE PADAWAN WHO SURVIVED · FREE TO SHARE", "chapLabel": "▌ CHAPTERS · 8 TOTAL", "pubPdf": "cal_public.pdf", "weekPdf": "cal_byweek.pdf", "quote": "I'm a Jedi Knight."}, "forge": {"helmet": {"name": "Ginger Hair + Styling", "type": "HEAD · 01", "kind": "Style/Wig", "hours": 2, "cost": 15, "priority": "CRITICAL", "description": "Cal's swept-back ginger hair — short sides, longer textured top. Your own hair if it's the right colour, or a styled ginger wig. Survivor adds a short ginger beard.", "tip": "Matte clay, not shiny gel. A few stray strands forward beats a helmet of hairspray — Cal looks lived-in, not polished.", "files": []}, "chestpanel": {"name": "Henley Base Layer", "type": "TORSO · 04", "kind": "Buy", "hours": 1, "cost": 18, "priority": "HIGH", "description": "A long-sleeve waffle-knit henley in cream, oatmeal or olive — the layer that sits closest to the skin under everything else. The button placket reads as Cal up close.", "tip": "Waffle/thermal texture sells it. Roll or push the sleeves so the arm wraps show.", "files": []}, "shoulders": {"name": "Layered Tunic / Overshirt", "type": "TORSO · 02", "kind": "Buy/Sew", "hours": 2, "cost": 22, "priority": "HIGH", "description": "The mid layer — a rough-spun tunic or henley-overshirt that peeks out under the poncho or jacket. Cal is all about stacked, slightly mismatched earthy layers.", "tip": "Pick a tone one shade off the base layer so the layers read separately, not as one block of fabric.", "files": []}, "chestplate": {"name": "Poncho (Fallen Order) / Vest (Survivor)", "type": "TORSO · 03", "kind": "Buy/Sew", "hours": 4, "cost": 30, "priority": "CRITICAL", "description": "The single piece that names your era. Fallen Order: a short asymmetric poncho/half-cape over one shoulder. Survivor: a weathered leather-look jacket or vest. This is the silhouette everyone recognises.", "tip": "Distress it — Cal's been through it. Sand the edges, rub in a little brown chalk pastel, fray the hem slightly. Brand-new fabric is the #1 tell.", "files": []}, "cape": {"name": "Neck Scarf / Cowl", "type": "OUTER · 07", "kind": "Buy/Sew", "hours": 1, "cost": 10, "priority": "MEDIUM", "description": "A loosely-wound neck scarf in a muted rust, grey or olive. Frequently part of Cal's look across both games and a quick way to add texture.", "tip": "Wind it loose and a little messy. A frayed/raw edge looks more screen-accurate than a clean hem.", "files": []}, "codpiece": {"name": "Arm Wraps", "type": "WAIST · 06", "kind": "Buy/Sew", "hours": 2, "cost": 10, "priority": "CRITICAL", "description": "Long cloth strips wound around both forearms and wrists — one of Cal's signature details. Wind from wrist to elbow over the pushed-up henley sleeves.", "tip": "Cut strips from an old cream/tan bedsheet. Wind firmly, overlap each pass, and pin or tuck the ends so they don't unravel mid-day.", "files": []}, "gloves": {"name": "Fingerless / Partial Gloves", "type": "ARM · 11", "kind": "Buy", "hours": 1, "cost": 8, "priority": "MEDIUM", "description": "Worn leather-look fingerless gloves or a single partial glove, depending on the reference you pick. Ties the hands into the wrapped-forearm look.", "tip": "Optional but it finishes the arms. Brown or tan, scuffed — never black gym gloves.", "files": []}, "belt": {"name": "Utility Belt + Pouches", "type": "WAIST · 05", "kind": "Buy", "hours": 1, "cost": 18, "priority": "HIGH", "description": "A wide brown leather-look belt with a pouch or two and a saber clip/hook on the side. Practical, scavenger-Jedi styling.", "tip": "Add a D-ring or belt clip so the saber hangs at the hip when not in hand — sells the 'Jedi at rest' look in photos.", "files": []}, "shins": {"name": "Trousers / Cargo Pants", "type": "LEGS · 09", "kind": "Buy", "hours": 1, "cost": 20, "priority": "MEDIUM", "description": "Earthy tapered trousers or light cargo/utility pants in brown, olive or grey. Slightly worn, tucked into the boots.", "tip": "Skip anything with logos or modern stitching. Thrift-store work trousers are perfect and cheap.", "files": []}, "boots": {"name": "Worn Brown Boots", "type": "LEGS · 10", "kind": "Buy", "hours": 1, "cost": 35, "priority": "HIGH", "description": "Lace-up or buckled brown boots, scuffed and lived-in. The grounded foundation of a walk-around-all-con cosplay.", "tip": "Comfort first — you'll be on your feet for hours. Rub boots with a little brown polish + a scuff cloth to age them.", "files": []}, "chain": {"name": "BD-1 Droid Backpack + Rebel Legion Fit", "type": "SYSTEM · 08", "kind": "3D Print", "hours": 6, "cost": 25, "priority": "HIGH", "description": "BD-1, Cal's little exploration droid, rides on his back — the detail that turns a generic Jedi into unmistakably Cal. Print the body, mount it on a hidden harness or backpack frame. Also check your layers against Rebel Legion (Jedi) standards.", "tip": "If you don't print, a plush/toy BD-1 zip-tied to a harness reads fine at distance. Rebel Legion = the good-guy costuming club; their reference photos are your accuracy checklist.", "files": []}, "saber": {"name": "Dual-Phase Blue Lightsaber", "type": "WEAPON · 12", "kind": "Buy", "hours": 2, "cost": 60, "priority": "CRITICAL", "description": "Cal's split/dual-phase hilt — it separates into two short emitters or runs as one long saber. Classic blue blade (he can swap colours in-game, but blue is iconic). Buy a hilt or print one; add a lit blade for photos.", "tip": "A separable dual-phase hilt is the showstopper — even a static prop that visibly splits gets every photo. A clip on the belt means hands free for the rest of the con.", "files": []}}, "weeks": [{"label": "Week 4", "task": "Pick your era (poncho or jacket). Order the poncho/jacket, henley, saber and BD-1 parts."}, {"label": "Week 3", "task": "Assemble the layers; first full fit. Cut and practice winding the arm wraps."}, {"label": "Week 2", "task": "Distress the poncho/jacket and boots. Build/mount BD-1 on its harness; clip the saber to the belt."}, {"label": "Week 1", "task": "Style the ginger hair, check against Rebel Legion refs, dress rehearsal — then game day."}], "files": [{"name": "BD-1 droid 3D model", "designer": "Cults3D", "url": "https://cults3d.com/en/search?q=bd-1+jedi+fallen+order"}, {"name": "Cal Kestis dual-phase saber STL", "designer": "Thingiverse", "url": "https://www.thingiverse.com/search?q=cal+kestis+lightsaber"}, {"name": "Cal Kestis costume + poncho reference", "designer": "Etsy / eBay", "url": "https://www.etsy.com/search?q=cal%20kestis%20cosplay"}, {"name": "Rebel Legion Jedi standards", "designer": "Rebel Legion", "url": "https://rebellegion.com/"}], "checklist": {"print": [{"name": "BD-1 droid body", "detail": "Rides on your back — the signature."}, {"name": "Dual-phase saber hilt", "detail": "Optional if buying a hilt instead."}, {"name": "Saber belt clip / D-ring", "detail": "Hangs the hilt at the hip."}], "buy": [{"name": "Waffle-knit henley", "detail": "Cream / oatmeal / olive base layer."}, {"name": "Poncho or weathered jacket", "detail": "Names your era — distress it."}, {"name": "Arm wraps + scarf", "detail": "Cloth strips, wound firmly, frayed edges."}, {"name": "Belt + pouches", "detail": "Brown, with a saber clip."}, {"name": "Trousers + worn brown boots", "detail": "Earthy, scuffed, comfortable."}, {"name": "Dual-phase blue saber", "detail": "Separable hilt is the showstopper."}, {"name": "Ginger wig (optional)", "detail": "If your hair isn't the right colour."}, {"name": "BD-1 plush (optional)", "detail": "Stand-in if you don't print one."}]}, "chapters": [{"num": "01", "title": "Mission Brief", "body": "<p class='lead'>This builds <span class='accent'>Cal Kestis</span> — the Padawan who survived Order 66 and clawed his way back to Jedi Knight across <i>Jedi: Fallen Order</i> and <i>Jedi: Survivor</i>.</p><p>Cal is the friendliest Jedi on the whole roster to build. There's no armour to print, no helmet to vacuum-form — it's a <span class='accent'>cloth and layers</span> build: a henley, a poncho or jacket, arm wraps, a scarf, worn boots, and one little droid riding on your back. If you've never made a costume before, start here.</p><div class='reader-callout'><div class='label'>▌ WHY CAL IS A GREAT FIRST BUILD</div><p>Almost everything can be thrifted or bought. The only optional print is BD-1 and the saber hilt — and both have plush/buy stand-ins. You can land a convincing Cal for the price of a few charity-shop layers and a saber.</p></div>"}, {"num": "02", "title": "Pick Your Era", "body": "<p class='lead'>One character, two unmistakable silhouettes. Choose before you buy a single thing.</p><ul><li><b>Fallen Order (the poncho)</b> — younger Cal, scruffier, the short asymmetric poncho/half-cape over one shoulder. The most recognisable Cal look.</li><li><b>Survivor (the jacket)</b> — older Cal, a weathered leather-look jacket or vest, often a short ginger beard, a slightly rougher and more worn feel.</li></ul><p>The <span class='accent'>layers underneath are nearly identical</span> — henley, wraps, belt, boots. Only the outer piece and the facial hair really change. That means you can build the base once and swap the top layer to switch eras later.</p><div class='reader-callout'><div class='label'>▌ FIRST-TIMER PICK</div><p>The Fallen Order poncho is the easier sew and the more iconic shape. If you're not sure, build that one.</p></div>"}, {"num": "03", "title": "The Layers", "body": "<p class='lead'>Cal isn't one outfit — he's three or four earthy layers stacked so they all peek through. Get the layering right and you're 80% there.</p><h3>Build from the skin out</h3><ul><li><b>Base:</b> a waffle-knit henley, cream or olive, sleeves pushed up.</li><li><b>Mid:</b> a rough tunic or overshirt one shade off the base.</li><li><b>Outer:</b> the poncho (Fallen Order) or jacket/vest (Survivor).</li><li><b>Accent:</b> a loose neck scarf in rust, grey or olive.</li></ul><div class='reader-callout'><div class='label'>▌ THE #1 TELL</div><p>Brand-new fabric. Cal has been crawling through wrecks and jungles — your fabric should look like it too. Sand the edges, rub in a little brown chalk pastel, fray a hem or two. Five minutes of weathering beats five hours of sewing.</p></div>"}, {"num": "04", "title": "Arm Wraps & Hands", "body": "<p class='lead'>The wound forearm wraps are pure Cal — a tiny detail people clock instantly.</p><p>Cut long strips from an old cream or tan bedsheet, push your henley sleeves up, and wind firmly from wrist toward elbow, overlapping each pass. <span class='accent'>Pin or tuck the ends</span> so they survive a full day of waving a saber around.</p><ul><li>Wind <b>both</b> forearms — asymmetry here looks like a mistake, not a design.</li><li>Add scuffed brown fingerless gloves if your reference has them.</li><li>Fray the strip ends slightly — clean hems look like bandages, frayed looks battle-worn.</li></ul><div class='reader-callout'><div class='label'>▌ TEST IT EARLY</div><p>Practice winding before game day. Wraps that unravel an hour in are the most common Cal failure — a stitch or two to close the loop is worth it.</p></div>"}, {"num": "05", "title": "BD-1 — The Detail That Sells It", "body": "<p class='lead'>A generic Jedi in a poncho is just a Jedi. Put <span class='accent'>BD-1 on your back</span> and you are unmistakably Cal Kestis.</p><p>BD-1 is Cal's little exploration droid and his constant companion. Mounting it is what earns the double-takes and the photo requests.</p><h3>Three ways to do it</h3><ul><li><b>Print it</b> — a 3D-printed BD-1 body on a hidden harness or backpack frame is the screen-accurate route (~6 hrs of print + assembly).</li><li><b>Plush / toy</b> — an official BD-1 plush zip-tied to a harness reads perfectly at conversation distance and costs almost nothing in effort.</li><li><b>Skip the back, carry it</b> — hold BD-1 like he's mid-scan for photos.</li></ul><div class='reader-callout'><div class='label'>▌ HARNESS TIP</div><p>Hide the straps under the poncho or scarf so BD-1 looks like he's gripping you, not strapped on. Angle him to peek over one shoulder — that's the iconic pose.</p></div>"}, {"num": "06", "title": "The Dual-Phase Saber", "body": "<p class='lead'>Cal's lightsaber splits. That's the trick worth showing off.</p><p>His hilt is <span class='accent'>dual-phase</span> — it runs as one long blade or separates into two short emitters for the spinning double-blade style. A separable hilt, even a static prop that just visibly comes apart, gets you in every photo.</p><ul><li><b>Buy</b> a Cal/dual-phase hilt, or <b>print</b> one from the STL files.</li><li>Blue is the iconic blade — he can swap colours in-game, but blue is the signature.</li><li>Add a lit blade for hero shots; clip the hilt to your belt the rest of the day.</li></ul><div class='reader-callout'><div class='label'>▌ HANDS-FREE</div><p>A belt clip or D-ring lets the saber hang at your hip, freeing your hands for BD-1 and for navigating a crowded con floor. It also nails the 'Jedi at rest' silhouette.</p></div>"}, {"num": "07", "title": "Game Day", "body": "<p class='lead'>Layers on, droid up, saber clipped — go survive the con.</p><h3>The final pass</h3><ul><li>Style the ginger hair matte (and the beard for Survivor) — no shiny gel.</li><li>Check your layers against <span class='accent'>Rebel Legion</span> Jedi reference photos — they're the good-guy costuming club and their standards are your accuracy checklist.</li><li>Pack a stain pen and safety pins — wraps loosen, fabric snags.</li><li>Walk around the house first: BD-1's harness should be comfortable for hours, not minutes.</li></ul><div class='reader-callout'><div class='label'>▌ STAY IN CHARACTER</div><p>Cal is earnest, a little awkward, genuinely kind. When someone asks who you are, just grin and say it: \"I'm a Jedi Knight.\" BD-1 does the rest.</p></div><div class=\"reader-callout\"><div class=\"label\">● ●  MORE GAME DAY LINES</div><ul><li>&ldquo;Trust only in the Force.&rdquo; <i>&mdash; Jaro Tapal's dying words — Cal's mantra, and the last line of Fallen Order</i></li><li>&ldquo;I don't plan to.&rdquo; <i>&mdash; his mic-drop reply when the Second Sister says he can't hide forever</i></li></ul></div><div class=\"reader-callout\"><div class=\"label\">😄 FOR LAUGHS — KID EDITION</div><ul><li>Trust only in the Force. And BD-1. And maybe pizza.</li><li>I can wall-run. The couch totally counts as a wall, right?</li><li>Don't worry, BD-1 has a stim for that. Even scraped knees.</li></ul></div>"}, {"num": "08", "title": "Saber Craft", "body": "<p class=\"lead\">The blade is half the costume — fight like the character. <span class=\"accent\">Self-taught / interrupted Padawan</span>, wielded single, splits to dual JarKai.</p><div class=\"reader-callout\"><div class=\"label\">▌ STYLE · SELF-TAUGHT / INTERRUPTED PADAWAN</div><p>An adaptive survivor's style — a Padawan foundation rebuilt on the run, switching between one long blade and two short ones as the fight demands. Canon never assigns him a form, but the mix reads closest to Form VI Niman: a balanced jack-of-all-trades rather than one perfected discipline. Cal's training was cut off at Order 66, so his style is patchwork by necessity — and versatile because of it.</p></div><div class=\"reader-table\"><div class=\"reader-table-row\"><span class=\"col-key\">BLADE</span><span class=\"col-val\"><span style=\"color:#2f7fe8\">⬤</span> Blue — dual-phase split hilt — one long blade joined</span></div><div class=\"reader-table-row\"><span class=\"col-key\">BLADE</span><span class=\"col-val\"><span style=\"color:#2f7fe8\">⬤</span> Blue — second short emitter when the hilt splits</span></div><div class=\"reader-table-row\"><span class=\"col-key\">WIELD</span><span class=\"col-val\">single, splits to dual JarKai</span></div></div><div class=\"reader-callout\"><div class=\"label\">▌ MORE THAN ONE BLADE — THE CRAFT</div><ul><li>Split mode: one short blade leads and probes while the other guards your open side — never both attacking at once.</li><li>Short blades mean short reach — cover the difference with footwork, not bigger swings.</li><li>Rejoin the hilt before moving through crowds or doorways; two loose blades need double the spacing.</li></ul></div><h3>Drill it</h3><p>Drill the switch: five slow cuts as one long blade, split the hilt, five paired cuts with the short blades, then rejoin. Smooth transitions are the whole style.</p><div class=\"reader-callout\"><div class=\"label\">⚠ DUEL SAFELY</div><p>Duel-grade polycarbonate blades only, never thin display tubes. Agree intensity before you start, no strikes to head or hands, and staff or dual spins need a full 3m of clear space.</p></div>"}]};


/* ===== Chewbacca ===== */
window.OPS.chewie = {"meta": {"word": "CHEWIE", "accent": "#7a4a28", "body": "creature", "budget": 420, "btn": "⚔ REBEL", "dur": "8 weeks", "hrs": "50–100 hrs", "parts": "Fur suit + bandolier + bowcaster", "budgetRange": "€250–600+", "lead": "The roster's first FUR build — a head-to-toe Wookiee fursuit, not an armour shell. This is a sewing-and-fur-grooming project: a brown shag bodysuit, a separate animatronic-optional head, one diagonal leather bandolier of silver ammo boxes, and the bowcaster. Advanced, hot to wear, and worth every hour.", "ruleLabel": "▌ THE ONE RULE", "rule": "Fur direction is everything. Brush it ALL downward like rain off a dog, hide every seam in the flow, and Chewie reads from across the room. Get the fur right and the rest is set dressing.", "intro": "OPERATION CHEWIE", "introSub": "FALCON ARCHIVE · BUILD MANUAL · FILE WOOKIEE-1", "footer": "OPERATION CHEWIE · BUILD MANUAL · LET THE WOOKIEE WIN · FREE TO SHARE", "chapLabel": "▌ CHAPTERS · 7 TOTAL", "pubPdf": "chewie_public.pdf", "weekPdf": "chewie_byweek.pdf", "quote": "RRRRGH-GHHHHHRRRR-AAARRRWHHGGWWWW. (Wookiee for \"let's go.\")"}, "forge": {"helmet": {"name": "Wookiee Head & Face", "type": "HEAD · 01", "kind": "Craft", "hours": 25, "cost": 130, "priority": "CRITICAL", "description": "A separate furred head/hood over a balaclava or foam base, with a sculpted muzzle, deep-set glass eyes, a black leather nose, and visible teeth. The face is what makes it Chewbacca and not a brown bear — long fur on the crown sweeping back, shorter groomed fur on the muzzle.", "tip": "Build the muzzle on a buckram or foam armature so it holds shape; line up your real eyes to look out through the fur shadow under the brow, not through the fake eyes.", "files": []}, "shoulders": {"name": "Fur Bodysuit (Torso)", "type": "BODY · 02", "kind": "Buy/Sew", "hours": 22, "cost": 110, "priority": "CRITICAL", "description": "The core garment: a one-piece (or jacket-plus-trousers) shag-fur bodysuit in mixed brown / grey-brown tones. Chewie's fur is long, layered and slightly unkempt — never one flat solid colour.", "tip": "Use a stretch backing where you bend (elbows, knees, armpits) so you can actually move; sew with fur pile pointing DOWN and tucked into every seam.", "files": []}, "chestplate": {"name": "No Armour", "type": "BODY · 03", "kind": "Skip", "hours": 0, "cost": 0, "priority": "LOW", "description": "Chewbacca wears no armour or chest plate — he is pure fur. This slot stays empty; all the visual weight goes to the fur and the single bandolier.", "tip": "Resist adding 'stuff' to the chest. The clean diagonal strap against fur is the whole silhouette.", "files": []}, "chestpanel": {"name": "Undersuit & Cooling", "type": "BODY · 04", "kind": "Buy", "hours": 2, "cost": 35, "priority": "HIGH", "description": "A moisture-wicking base layer worn under the fur — this is a hot, heavy suit and heat is the real enemy. Compression top, leggings, a sweatband for the head.", "tip": "Freeze a couple of cooling-vest ice packs and bottles of water; budget for them now, you'll thank yourself on game day.", "files": []}, "belt": {"name": "Bandolier (Ammo Boxes)", "type": "STRAP · 05", "kind": "Buy/Sew", "hours": 6, "cost": 45, "priority": "CRITICAL", "description": "The single diagonal leather strap worn over the LEFT shoulder, crossing to the right hip, studded with rectangular silver ammunition boxes. After the fur, this is the most recognisable Chewbacca element.", "tip": "Real Chewie wears it left-shoulder-to-right-hip. The boxes are simple silver-painted blocks — wood, foam or 3D print — riveted evenly along the strap.", "files": []}, "codpiece": {"name": "Hip & Seat Fur", "type": "BODY · 06", "kind": "Sew", "hours": 3, "cost": 0, "priority": "MEDIUM", "description": "Blends the bodysuit's waist and hip so no skin, base layer or seam shows when you sit, reach, or where the bandolier ends at the hip. Continuous fur from chest to thigh.", "tip": "Reinforce the seat seam — it takes the most stress when you sit down for photos all day.", "files": []}, "cape": {"name": "No Cape", "type": "OUTER · 07", "kind": "Skip", "hours": 0, "cost": 0, "priority": "LOW", "description": "Chewbacca wears no cape, cloak, or robe — the fur is the outer layer. Leave this slot empty.", "tip": "Not used for this build.", "files": []}, "chain": {"name": "Reference & Fit (Rebel Legion)", "type": "SYSTEM · 08", "kind": "Plan", "hours": 3, "cost": 0, "priority": "MEDIUM", "description": "Chewbacca is a hero of the Rebellion — check your build against Rebel Legion reference photos and their Costume Reference for proportions, fur colour and bandolier placement.", "tip": "Rebel Legion = the good guys. Study side and back photos, not just the front — the fur flow on the back of the head is a common giveaway.", "files": []}, "shins": {"name": "Fur Legs / Height Stilts", "type": "LEGS · 09", "kind": "Craft", "hours": 10, "cost": 60, "priority": "HIGH", "description": "Furred legs continuing the bodysuit. Optional advanced add-on: platform boots or short stilts to push toward Chewie's ~2.3m height. Even +10–15cm changes the whole read.", "tip": "Stilts are advanced — only attempt if you've practised walking in them. A safe win is thick platform soles plus an extended head crown for cheap, stable height.", "files": []}, "boots": {"name": "Furred Feet / Paws", "type": "LEGS · 10", "kind": "Craft", "hours": 5, "cost": 35, "priority": "MEDIUM", "description": "Big furred feet or paw-shoe covers over sturdy trainers, so the fur runs unbroken to the floor with no human shoe peeking out.", "tip": "Build them over shoes you can stand in all day — comfort beats screen-accuracy when you're carrying this much suit.", "files": []}, "gloves": {"name": "Furred Hands & Claws", "type": "ARM · 11", "kind": "Craft", "hours": 6, "cost": 30, "priority": "HIGH", "description": "Furred gloves with shorter groomed fur on the back of the hand, exposed-look leathery palm/finger pads, and sculpted dark claws. Hands are in every photo — don't skimp.", "tip": "Leave the fingertips functional so you can actually hold the bowcaster and shake hands; trim the palm fur short so it doesn't look mitten-like.", "files": []}, "saber": {"name": "Bowcaster", "type": "WEAPON · 12", "kind": "Buy/Print", "hours": 8, "cost": 50, "priority": "CRITICAL", "description": "Chewbacca's signature crossbow-style weapon — a stocked body with a curved limb assembly and a string/energy element. The one prop everyone recognises in his hands.", "tip": "3D print or kitbash from a toy crossbow; weather the metal and wood, and add the worn-leather wrap on the grip. Check your event's prop rules before you go.", "files": []}}, "weeks": [{"label": "Week 8", "task": "Plan + measure. Order fur (mixed brown/grey-brown long pile), backing fabric, base layer, leather strap and silver ammo-box stock, bowcaster STL or toy donor."}, {"label": "Week 7", "task": "Pattern the bodysuit on a duct-tape dummy or old coveralls; do a calico/cheap-fabric mockup before cutting the real fur."}, {"label": "Week 6", "task": "Cut and sew the fur torso, arms and legs — pile pointing down, seams hidden. Test fit and check range of motion."}, {"label": "Week 5", "task": "Build the head: muzzle armature, set the eyes and leather nose, install teeth, fur the crown sweeping back."}, {"label": "Week 4", "task": "Hands, claws and furred feet. Make sure you can grip the bowcaster and walk all day in the feet."}, {"label": "Week 3", "task": "Build the bandolier — rivet silver ammo boxes evenly along the leather strap (left shoulder to right hip). Finish and weather the bowcaster."}, {"label": "Week 2", "task": "Grooming pass: brush, blend and trim ALL fur downward; hide every seam; test height add-on (platforms/stilts) safely."}, {"label": "Week 1", "task": "Full dress rehearsal with cooling packs and water. Practise the walk and the roar. Game day."}], "files": [{"name": "Bowcaster 3D model (search)", "designer": "Cults3D community", "url": "https://cults3d.com/en/search?q=chewbacca+bowcaster"}, {"name": "Wookiee / Chewbacca fur reference (search)", "designer": "Rebel Legion reference", "url": "https://www.google.com/search?q=chewbacca+costume+reference+rebel+legion"}, {"name": "Long-pile fur fabric for fursuits (search)", "designer": "Etsy sellers", "url": "https://www.etsy.com/search?q=long+pile+faux+fur+fursuit+brown"}], "checklist": {"print": [{"name": "Bowcaster", "detail": "Print the body and curved limbs, or kitbash from a toy crossbow donor."}, {"name": "Bandolier ammo boxes", "detail": "Print rectangular silver boxes to rivet along the strap (or use wood/foam blocks)."}, {"name": "Claws & teeth", "detail": "Print or sculpt dark claws for the gloves and teeth for the muzzle."}, {"name": "Eye blanks", "detail": "Print or buy follow-me doll/taxidermy eyes for the head."}], "buy": [{"name": "Long-pile faux fur", "detail": "Several metres in mixed brown / grey-brown; long shag, not flat."}, {"name": "Stretch backing fabric", "detail": "For elbows, knees and armpits so the suit moves."}, {"name": "Moisture-wicking base layer", "detail": "Compression top + leggings + sweatband — heat management."}, {"name": "Leather strap", "detail": "Wide brown leather/pleather for the single diagonal bandolier."}, {"name": "Cooling packs & water", "detail": "Ice packs, a cooling towel and bottled water for the day."}, {"name": "Sturdy shoes for paws", "detail": "Comfortable trainers to build the furred feet over (plus optional platforms/stilts)."}, {"name": "Fur grooming kit", "detail": "Slicker brush, sharp shears and a comb for blending seams and trimming the muzzle."}]}, "chapters": [{"num": "01", "title": "Mission Brief", "body": "<p class='lead'>This builds <span class='accent'>Chewbacca</span> — the Wookiee co-pilot of the Millennium Falcon and Han Solo's partner. It is the roster's first <span class='accent'>FUR</span> build, and that changes everything.</p><p>You are not printing an armour shell here. You are sewing and grooming a head-to-toe fursuit: a long brown shag bodysuit, a separate furred head with a sculpted muzzle, furred hands and feet, one diagonal leather bandolier of silver ammo boxes, and the bowcaster. Chewie stands about <span class='accent'>2.3m tall</span>, so height is part of the costume too.</p><div class='reader-callout'><div class='label'>▌ WHY THIS IS ADVANCED</div><p>Fursuit fabrication is its own craft — patterning fur, hiding seams, building a head, and managing heat. Take your time, mock things up in cheap fabric first, and you'll be fine. This is a marathon, not a print job.</p></div>"}, {"num": "02", "title": "The Fur Is the Costume", "body": "<p class='lead'>Get the fur right and Chewie reads from across the room. Get it wrong and you're a brown bear.</p><p>Chewbacca's fur is <span class='accent'>long, layered, and a mix of browns and grey-browns</span> — never one flat solid colour. Buy long-pile (shag) faux fur, not the short cheap stuff. Blend two or three close shades if you can.</p><h3>The two iron rules of fur</h3><ul><li><b>Pile points DOWN.</b> Brush every panel so the fur falls like rain off a dog — head, shoulders, arms, everything flows toward the floor.</li><li><b>Hide every seam.</b> Sew with the fur tucked inward, then brush the pile back over the join so the seam disappears into the flow.</li></ul><div class='reader-callout'><div class='label'>▌ MOCK IT UP FIRST</div><p>Never cut your good fur first. Pattern the suit on a duct-tape dummy or an old set of coveralls, sew a cheap-fabric test version, fix the fit, THEN cut the real fur. Fur is expensive and unforgiving.</p></div>"}, {"num": "03", "title": "Building the Head", "body": "<p class='lead'>The face is what makes it Chewbacca and not a generic creature.</p><p>The head is a separate piece — a furred hood over a balaclava or a lightweight foam/buckram base. The key features are a <span class='accent'>sculpted muzzle</span>, deep-set glass eyes under a heavy brow, a <span class='accent'>black leather nose</span>, and a hint of teeth in the mouth.</p><h3>Seeing out</h3><p>You look out through the fur shadow under the brow, not through the fake eyes. Position your real eyeline in the dark gap beneath the sculpted brow so the costume eyes stay screen-accurate and you can still walk safely.</p><div class='reader-callout'><div class='label'>▌ MUZZLE THAT HOLDS SHAPE</div><p>Build the muzzle on a foam or buckram armature so it keeps its form all day. Long fur sweeps back over the crown; the muzzle fur is shorter and groomed. That length contrast sells the face.</p></div>"}, {"num": "04", "title": "The Bandolier & Bowcaster", "body": "<p class='lead'>Two props, and they're both non-negotiable. After the fur, these are what people point at.</p><h3>The bandolier</h3><p>A single diagonal leather strap, worn over the <span class='accent'>LEFT shoulder crossing to the right hip</span>, studded with evenly-spaced rectangular silver ammunition boxes. The boxes are simple — wood, foam or 3D-printed blocks painted silver and riveted along the strap.</p><h3>The bowcaster</h3><p>Chewie's signature crossbow-style weapon: a stocked body, a curved limb assembly, and a string/energy element. 3D print it, or kitbash from a toy crossbow. Weather the metal and wood and add a worn-leather grip wrap.</p><div class='reader-callout'><div class='label'>▌ CHECK PROP RULES</div><p>Many conventions have weapon and prop-length rules. Check your event's policy before you build, and never bring anything that looks like a real firearm to a public space.</p></div>"}, {"num": "05", "title": "Hands, Feet & Height", "body": "<p class='lead'>Your hands are in every single photo. Don't skimp on them.</p><p>Build furred gloves with shorter groomed fur on the back, a leathery-look palm, and sculpted dark claws — but keep the fingertips <span class='accent'>functional</span> so you can hold the bowcaster and shake hands. The feet are furred paw-covers over sturdy trainers so the fur runs unbroken to the floor with no human shoe showing.</p><h3>Reaching for 2.3m</h3><ul><li><b>Easy win:</b> thick platform soles plus an extended head crown adds height cheaply and safely.</li><li><b>Advanced:</b> short stilts get you closer to true Wookiee height — but only if you've practised walking in them.</li></ul><div class='reader-callout'><div class='label'>▌ SAFETY FIRST ON STILTS</div><p>Stilts are an advanced add-on. If you've never used them, skip them this year. A stable costume you can wear all day beats a tall one you can't walk in.</p></div>"}, {"num": "06", "title": "Surviving the Suit", "body": "<p class='lead'>The fursuit is hot, heavy and limits your senses. Respect that and you'll have a great day.</p><p>This is the part new fursuit builders underestimate. A full fur suit traps heat fast, so <span class='accent'>heat management is a real part of the build</span>, not an afterthought.</p><h3>Your survival kit</h3><ul><li><b>Base layer:</b> moisture-wicking compression top and leggings under the fur.</li><li><b>Cooling:</b> frozen ice packs in a cooling vest, a damp cooling towel, and lots of water.</li><li><b>A spotter:</b> a friend out of costume to guide you, since your vision and hearing are reduced.</li><li><b>Cool-down breaks:</b> a quiet, shaded place to take the head off every hour.</li></ul><div class='reader-callout'><div class='label'>▌ THE BUDDY RULE</div><p>Never wear a full suit alone in a crowd. Your peripheral vision is gone and stairs are dangerous. A handler makes the whole day safer and more fun.</p></div>"}, {"num": "07", "title": "Game Day", "body": "<p class='lead'>Full dress rehearsal before the event, then let the Wookiee win.</p><p>Do a complete dress run a few days early — suit, head, bandolier, hands, feet and bowcaster all together. Walk around, sit down, pick the bowcaster up, and check nothing rides up or pinches.</p><h3>Final checklist</h3><ul><li>Fur brushed and blended, all seams hidden, everything flowing down.</li><li>Bandolier on the left shoulder, boxes even, bowcaster weathered.</li><li>Cooling packs frozen, water bottle filled, handler briefed.</li><li>Practise the <span class='accent'>roar</span> — Chewie doesn't speak Basic, he growls and roars.</li></ul><div class='reader-callout'><div class='label'>▌ STAY IN CHARACTER</div><p>Chewbacca never talks — just warm Wookiee growls, a big head tilt, and gentle bear hugs. Lean into it. Let the Wookiee win.</p></div><div class=\"reader-callout\"><div class=\"label\">● ●  MORE GAME DAY LINES</div><ul><li>&ldquo;The happy growl that answers Han's \"Chewie, we're home.\" (The Force Awakens)&rdquo; <i>&mdash; soft, rumbly, pure joy</i></li><li>&ldquo;The Tarzan yell while swinging onto an AT-ST at the Battle of Endor (Return of the Jedi)&rdquo; <i>&mdash; full volume, arms wide</i></li><li>&ldquo;The grumpy holochess growl that makes C-3PO say \"Let the Wookiee win.\" (A New Hope)&rdquo; <i>&mdash; low warning rumble, then look very smug</i></li></ul></div><div class=\"reader-callout\"><div class=\"label\">😄 FOR LAUGHS — KID EDITION</div><ul><li>RRAAARGH. (Wookiee for \"that was MY sandwich.\")</li><li>Hhrrmmm-rrgh. (Translation: \"let the Wookiee win the board game.\")</li><li>AARRWGH! (That's Wookiee for \"free hugs, galaxy-wide.\")</li></ul></div>"}]};


/* ===== Mace Windu ===== */
window.OPS.mace = {"meta": {"word": "MACE", "accent": "#7b4ea8", "body": "cloth", "budget": 130, "btn": "✦ JEDI", "dur": "4 weeks", "hrs": "10–25 hrs", "parts": "Dark robes + purple saber", "budgetRange": "€70–260+", "lead": "The senior Jedi on the High Council, built the way it should be: layered charcoal and dark-brown robes, a heavy hooded outer robe, a calm bald head — and the one purple blade in the whole galaxy. Beginner-friendly soft goods, but the colour of that saber is everything.", "ruleLabel": "▌ THE ONE RULE", "rule": "The blade is PURPLE — not blue, not red. That single colour is the whole costume. Get a saber you can set to purple, or paint/gel one purple, before you worry about anything else.", "intro": "OPERATION MACE", "introSub": "JEDI ARCHIVE · BUILD MANUAL · FILE MACE-01", "footer": "OPERATION MACE · JEDI BUILD MANUAL · THIS PARTY'S OVER · FREE TO SHARE", "chapLabel": "▌ CHAPTERS · 8 TOTAL", "pubPdf": "mace_public.pdf", "weekPdf": "mace_byweek.pdf", "quote": "This party's over."}, "forge": {"helmet": {"name": "Bald Head & Calm Face", "type": "HEAD · 01", "kind": "Style/Wig", "hours": 1, "cost": 12, "priority": "CRITICAL", "description": "Mace is clean-shaven and bald with a calm, commanding stare. Shave your head, or use a bald cap blended and powdered to match your skin. No beard, no long hair — a still, serious face does the acting.", "tip": "If you use a bald cap, powder it matte so it never shines under lights — a shiny cap reads as plastic across the room.", "files": []}, "shoulders": {"name": "Inner Tunic (Base Layer)", "type": "TORSO · 02", "kind": "Buy/Sew", "hours": 2, "cost": 20, "priority": "HIGH", "description": "The under-tunic that sits against the neck and shows at the collar. Mace runs dark — near-black charcoal or very dark brown, not the tan of Obi-Wan. Wrap-front, crosses in a shallow V at the throat.", "tip": "Pick a matte linen-look or wool-blend fabric. Anything shiny instantly reads as a cheap costume, not a Jedi Master.", "files": []}, "chestplate": {"name": "Outer Tunic & Tabards", "type": "TORSO · 03", "kind": "Buy/Sew", "hours": 3, "cost": 30, "priority": "CRITICAL", "description": "The signature Jedi silhouette: a dark charcoal/brown outer tunic that crosses over the body, plus two long tabards (front-and-back straps) running down the chest under the belt. This layering over dark cloth is what makes Mace read as Mace and not just 'a Jedi'.", "tip": "The tabards should hang straight and even. Pin them to the obi so they don't drift sideways when you move or fight.", "files": []}, "belt": {"name": "Obi Sash + Wide Leather Belt", "type": "WAIST · 04", "kind": "Buy/Sew", "hours": 1, "cost": 22, "priority": "HIGH", "description": "Two waist layers: a soft cloth obi sash wrapped around the middle, then a wide brown leather belt over it with a covered buckle and a saber clip/D-ring on the right hip. The belt holds the whole robe closed.", "tip": "Add the saber clip to the belt now, not on game day — you want the hilt to hang cleanly at the hip and detach fast for photos.", "files": []}, "codpiece": {"name": "Trousers", "type": "LEGS · 05", "kind": "Buy", "hours": 1, "cost": 15, "priority": "MEDIUM", "description": "Plain dark-brown trousers, loose but not baggy, tucked into the boots. They mostly disappear under the tunic and robe, so comfort and colour-match matter more than detail.", "tip": "Match the trouser brown to the boots so the leg reads as one clean line from knee to floor.", "files": []}, "cape": {"name": "Heavy Hooded Outer Robe", "type": "OUTER · 06", "kind": "Buy/Sew", "hours": 3, "cost": 40, "priority": "CRITICAL", "description": "The big dark-brown hooded Jedi robe worn over everything — heavier and darker than most. Wide sleeves, deep hood, hem just off the floor. This is the piece people photograph, so weight and drape matter: thin costume-shop capes ruin the whole look.", "tip": "Buy or sew it in a heavy wool-blend so it hangs with weight. Hem it to just above the floor — a robe that drags gets stepped on and looks sloppy.", "files": []}, "boots": {"name": "Brown Leather Boots", "type": "FEET · 07", "kind": "Buy", "hours": 1, "cost": 20, "priority": "MEDIUM", "description": "Plain brown leather boots, mid-calf, trousers tucked in. No buckles or zips showing. Comfortable enough to stand and pose in all day.", "tip": "Thrift or reuse a pair of plain brown boots and rub off any logos — screen-accurate boots are just clean and simple.", "files": []}, "gloves": {"name": "Hands (Bare)", "type": "HANDS · 08", "kind": "Style", "hours": 0, "cost": 0, "priority": "LOW", "description": "Mace fights bare-handed — no gloves. Nothing to build here; just keep the wrists of the tunic sleeves neat so the forearm reads clean when the saber comes up.", "tip": "Skip the gloves entirely. Adding them is a common mistake that makes the build look less accurate, not more.", "files": []}, "saber": {"name": "Purple Lightsaber", "type": "WEAPON · 09", "kind": "3D Print", "hours": 4, "cost": 35, "priority": "CRITICAL", "description": "THE defining piece. A silver, ridged-grip hilt with a purple blade — the only purple saber in the films. Buy a saber that can be set to purple, print/build a hilt and add a purple blade, or set an RGB/neopixel saber to amethyst. Everything else on the build supports this one prop.", "tip": "Test the exact purple under warm hall lighting before the con. Some 'purple' LEDs wash out pink or blue on camera — you want a deep violet that still reads purple in photos.", "files": []}}, "weeks": [{"label": "Week 4", "task": "Lock the purple saber first — buy or start the hilt. Order/gather dark robes, tabards, belt, boots."}, {"label": "Week 3", "task": "First fit: layer inner tunic, outer tunic and tabards. Confirm everything reads DARK, not tan."}, {"label": "Week 2", "task": "Hem the hooded robe off the floor. Fit the obi + leather belt and mount the saber clip."}, {"label": "Week 1", "task": "Bald head/cap test, dial the saber to the right purple, full dress rehearsal, then game day."}], "files": [{"name": "Mace Windu saber hilt STL", "designer": "Cults3D", "url": "https://cults3d.com/en/search?q=mace+windu+lightsaber"}, {"name": "Jedi robes & tabards (full costume)", "designer": "Etsy", "url": "https://www.etsy.com/search?q=jedi+robe+tunic+tabard+costume"}, {"name": "Rebel Legion Jedi standards", "designer": "Rebel Legion", "url": "https://rebellegion.com/"}], "checklist": {"print": [{"name": "Saber hilt (optional)", "detail": "Or buy a purple-capable saber instead."}, {"name": "Saber clip / D-ring", "detail": "Prints or buys; mounts on the belt."}], "buy": [{"name": "Inner + outer tunic", "detail": "Dark charcoal / dark brown, matte."}, {"name": "Tabards", "detail": "Two long front-and-back straps."}, {"name": "Obi sash + wide leather belt", "detail": "Cloth wrap under a brown belt."}, {"name": "Dark trousers", "detail": "Brown, tuck into boots."}, {"name": "Heavy hooded robe", "detail": "Dark brown, hemmed off the floor."}, {"name": "Brown leather boots", "detail": "Plain, no logos."}, {"name": "Bald cap (if needed)", "detail": "Blend + powder matte."}, {"name": "Purple lightsaber", "detail": "Set / build the blade PURPLE."}]}, "chapters": [{"num": "01", "title": "Mission Brief", "body": "<p class='lead'>This builds <span class='accent'>Mace Windu</span> — Jedi Master, senior member of the High Council, and the calmest, most dangerous man in the room.</p><p>It's a soft-goods (cloth) build, friendly for a first-timer but with room to go deep. Two jobs stand above everything else: run your robes <span class='accent'>darker</span> than a normal Jedi, and carry the one <span class='accent'>purple</span> blade in the galaxy.</p><div class='reader-callout'><div class='label'>▌ WHY THIS ONE IS EASIER THAN IT LOOKS</div><p>No armour, no makeup, no mask — it's layers of dark cloth plus a saber. If you can dress in order and hem a robe, you can build Mace.</p></div>"}, {"num": "02", "title": "Read the Character", "body": "<p class='lead'>Mace isn't loud. He's still, upright, and completely in control.</p><p>Everyone else in Jedi robes is playing a warrior. Mace plays the person the warriors listen to. That comes through in three things:</p><ul><li><b>Posture</b> — stand straight, shoulders level, chin steady. No slouching.</li><li><b>Stillness</b> — small, deliberate movements. He doesn't fidget.</li><li><b>The stare</b> — a calm, level look, not a scowl.</li></ul><p class='accent'>Get the bearing right and people will call you Mace before they even clock the saber.</p>"}, {"num": "03", "title": "Dark Robes & Tabards", "body": "<p class='lead'>Same Jedi silhouette as everyone else — but Mace runs dark.</p><p>Build it in layers: dark inner tunic, a crossed-over outer tunic, two long tabards down the chest, an obi sash, then a wide leather belt over the top. Finish with the heavy hooded robe.</p><div class='reader-callout'><div class='label'>▌ DARK, NOT TAN</div><p>This is the mistake that makes a Mace look like a generic Jedi: going too light. Use charcoal, near-black, and dark chocolate brown. If it looks like sand or cream, it's wrong.</p></div><p>Keep every fabric <span class='accent'>matte</span> — linen-look or wool-blend. Shine is the enemy.</p>"}, {"num": "04", "title": "The Purple Lightsaber", "body": "<p class='lead'>This is the whole costume in one prop.</p><p>Mace's is the only purple blade in the films — a silver, ridged-grip hilt with a deep violet blade. You have three routes:</p><ul><li><b>Easiest</b> — buy an RGB or neopixel saber and set it to purple.</li><li><b>Middle</b> — buy a fixed purple-blade saber.</li><li><b>Builder</b> — print or assemble a hilt and fit a purple blade.</li></ul><div class='reader-callout'><div class='label'>▌ TEST THE PURPLE ON CAMERA</div><p>Some 'purple' LEDs photograph pink or bordering-blue under hall lighting. Take a phone photo in a dim room before the con and confirm it still reads as a rich violet.</p></div>"}, {"num": "05", "title": "Head & Bearing", "body": "<p class='lead'>Bald head, clean face, calm eyes.</p><p>Shave your head if you can, or use a bald cap blended at the edges and powdered matte so it never shines. No beard, no wig, no gloves — Mace is deliberately plain so the robes and the blade carry the look.</p><div class='reader-callout'><div class='label'>▌ LESS IS MORE</div><p>Every extra accessory you add pulls you away from accurate. Bare hands, still face, one purple saber. That restraint IS the character.</p></div>"}, {"num": "06", "title": "Fit, Layer & Hem", "body": "<p class='lead'>A Jedi build lives or dies on the drape.</p><p>Layer in the right order every time: trousers and boots, inner tunic, outer tunic, tabards, obi, leather belt, then the hooded robe last. Pin the tabards to the obi so they stay straight when you move.</p><ul><li>Hem the outer robe to just <b>above the floor</b> — a dragging robe gets stepped on and looks messy.</li><li>Clip the saber to the belt so it detaches fast for photos.</li><li>Iron out every fold before you leave the house.</li></ul>"}, {"num": "07", "title": "Game Day", "body": "<p class='lead'>You're the Jedi the Council sends when it's serious.</p><p>Dress in order, check the robe hangs even, and let the saber hang at your hip until it's needed. Then stand tall, keep the face calm, and own the room.</p><div class='reader-callout'><div class='label'>▌ SIGNATURE MOVE</div><p>Ignite the purple blade, hold a steady level stare, and deliver the line. That's the whole character in three seconds.</p></div><p class='accent'>This party's over.</p><div class=\"reader-callout\"><div class=\"label\">● ●  MORE GAME DAY LINES</div><ul><li>&ldquo;I sense a plot to destroy the Jedi.&rdquo; <i>&mdash; grave and low — this is Council-chamber serious</i></li><li>&ldquo;He's too dangerous to be left alive!&rdquo; <i>&mdash; sharp and urgent, saber-point energy</i></li><li>&ldquo;Take a seat, young Skywalker.&rdquo; <i>&mdash; calm, final — no room for argument</i></li></ul></div><div class=\"reader-callout\"><div class=\"label\">😄 FOR LAUGHS — KID EDITION</div><ul><li>This recess... is over.</li><li>I sense a plot to destroy my snack. It was you.</li><li>You have been granted a seat at this lunch table, but we do not grant you the rank of sandwich-sharer.</li></ul></div>"}, {"num": "08", "title": "Saber Craft", "body": "<p class=\"lead\">The blade is half the costume — fight like the character. <span class=\"accent\">Juyo/Vaapad</span>, wielded single.</p><div class=\"reader-callout\"><div class=\"label\">▌ FORM VII · JUYO/VAAPAD — “The Way of the Vornskr”</div><p>The most dangerous form in the catalogue — a controlled storm that accepts the opponent's fury and feeds it straight back. Blindingly fast, tight arcs, total inner calm; the moment the calm slips, the form owns you instead. Vaapad exists because Mace built it — the only master disciplined enough to channel dark-side momentum without falling in.</p></div><div class=\"reader-table\"><div class=\"reader-table-row\"><span class=\"col-key\">BLADE</span><span class=\"col-val\"><span style=\"color:#8b45c6\">⬤</span> Purple — the only purple blade in the films</span></div><div class=\"reader-table-row\"><span class=\"col-key\">WIELD</span><span class=\"col-val\">single</span></div></div><h3>Drill it</h3><p>Shadow-drill accelerating figure-eights that never leave a hoop-sized guard in front of your chest: start slow, build speed each pass, and stop the instant your control (or your temper) wobbles.</p><div class=\"reader-callout\"><div class=\"label\">⚠ DUEL SAFELY</div><p>Duel-grade polycarbonate blades only, never thin display tubes. Agree intensity before you start, no strikes to head or hands, and staff or dual spins need a full 3m of clear space.</p></div>"}]};


/* ===== Finn ===== */
window.OPS.finn = {"meta": {"word": "FINN", "accent": "#b5793a", "body": "cloth", "budget": 130, "btn": "✦ RESISTANCE", "dur": "4 weeks", "hrs": "8–18 hrs", "parts": "Leather jacket + henley + saber", "budgetRange": "€80–240", "lead": "FN-2187 — the stormtrooper who put the blaster down and ran the other way. Two looks: the hero closet-cosplay in Poe's tan leather jacket over a grey-blue henley, or the full First Order trooper armour with the bloody handprint on the helmet. This guide defaults to the jacket — one of the most beginner-friendly, thriftable builds on the whole roster. Almost nothing to print, everything to feel.", "ruleLabel": "▌ THE ONE RULE", "rule": "Finn is the jacket. Get a real, lived-in tan/brown leather (or a good faux) with the sleeves pushed up over a grey-blue henley, and the rest falls into place. A stiff, shiny, brand-new jacket reads as a costume; a scuffed, worn one reads as a trooper who just defected. Weather it before you wear it.", "intro": "OPERATION FINN", "introSub": "RESISTANCE ARCHIVE · BUILD MANUAL · FILE FN-2187", "footer": "OPERATION FINN · RESISTANCE BUILD MANUAL · THE TROOPER WHO CHOSE · FREE TO SHARE", "chapLabel": "▌ CHAPTERS · 8 TOTAL", "pubPdf": "finn_public.pdf", "weekPdf": "finn_byweek.pdf", "quote": "That's not what I'm about."}, "forge": {"helmet": {"name": "Short Natural Hair", "type": "HEAD · 01", "kind": "Style/Wig", "hours": 1, "cost": 8, "priority": "MEDIUM", "description": "Finn's tight, close-cropped natural hair — no helmet, no wig needed for most builders. Your own hair kept short and neat is the whole look. This is the single biggest advantage the jacket build has over the trooper.", "tip": "Keep it matte and tidy. If you're going the trooper route instead, the FN-2187 helmet replaces this slot entirely — see the reader callout in Chapter 2.", "files": []}, "chestpanel": {"name": "Grey-Blue Henley", "type": "TORSO · 04", "kind": "Buy", "hours": 1, "cost": 20, "priority": "CRITICAL", "description": "The layer that names the hero look — a long-sleeve grey / blue-grey waffle or jersey henley worn under the jacket. This is the base Finn wears the moment he ditches the armour, and it's the piece people read first once the jacket opens.", "tip": "Grey-blue, not navy and not pure grey — think faded slate. A waffle/thermal texture sells it up close. Push the sleeves up so they bunch under the jacket cuffs.", "files": []}, "chestplate": {"name": "Tan/Brown Leather Jacket (Poe's)", "type": "TORSO · 03", "kind": "Buy", "hours": 3, "cost": 55, "priority": "CRITICAL", "description": "The single most important piece in the build. Finn borrows Poe's tan-to-brown leather flight jacket after the escape — quilted shoulders, worn collar, lived-in scuffs. This silhouette is what makes a stranger say 'Finn' from across the hall.", "tip": "Thrift a real leather jacket if you can — faux works but pick a soft, matte one that already looks worn. Distress the collar and elbows with fine sandpaper and a little brown shoe polish. Brand-new shine is the #1 tell.", "files": []}, "shoulders": {"name": "Undershirt / Layer Peek", "type": "TORSO · 02", "kind": "Buy", "hours": 1, "cost": 10, "priority": "LOW", "description": "A plain crew or henley collar that peeks at the neckline under the main henley — Finn's look is lightly layered, not a single flat shirt. Optional, but a second collar line adds depth in photos.", "tip": "Keep it a shade lighter or darker than the main henley so the layers read separately. One shade off, never the same fabric.", "files": []}, "belt": {"name": "Dark Trousers + Belt", "type": "WAIST · 05", "kind": "Buy", "hours": 1, "cost": 25, "priority": "HIGH", "description": "Dark, slightly tapered trousers — charcoal, brown or faded black — with a simple brown or black leather belt. Practical, grounded, nothing flashy. Finn dresses like someone who grabbed what fit and ran.", "tip": "Skip anything with logos, rips or modern athletic stitching. Thrift-store work or chino trousers are perfect and cheap. Slightly worn beats crisp and new.", "files": []}, "gloves": {"name": "Bare / Optional Fingerless Gloves", "type": "ARM · 11", "kind": "Buy", "hours": 1, "cost": 8, "priority": "LOW", "description": "Finn is usually bare-handed in the jacket look. If your reference or the weather calls for it, a pair of scuffed brown fingerless gloves ties the hands into the worn-leather palette.", "tip": "Optional and easy to skip. If you wear them, brown or tan and scuffed — never black gym gloves.", "files": []}, "shins": {"name": "Dark Utility Trousers Fit", "type": "LEGS · 09", "kind": "Buy", "hours": 1, "cost": 0, "priority": "MEDIUM", "description": "The lower half of the trouser line — tapered and tucked lightly at the boot, not pooling. This is a fit note rather than a separate purchase; it shares the trousers from the belt slot.", "tip": "Cuff or taper so the trouser breaks cleanly on the boot. A puddle of fabric at the ankle kills the grounded, ready-to-move silhouette.", "files": []}, "boots": {"name": "Worn Brown/Black Boots", "type": "LEGS · 10", "kind": "Buy", "hours": 1, "cost": 40, "priority": "HIGH", "description": "Lace-up brown or black boots, scuffed and comfortable — the foundation for a walk-around-all-con costume. Finn is always mid-motion; the boots should look like they've done some running.", "tip": "Comfort first — you'll be on your feet for hours. Rub in a little polish plus a scuff cloth to age them. Waterproof if your con floor is outdoors.", "files": []}, "saber": {"name": "Blue Lightsaber (Skywalker Hilt)", "type": "WEAPON · 12", "kind": "Buy", "hours": 2, "cost": 60, "priority": "HIGH", "description": "Finn famously grabs the Skywalker/Anakin blue lightsaber and swings it against Kylo Ren — the prop that turns a guy in a jacket into unmistakably Finn mid-fight. Buy a hilt (or print one) and add a lit or removable blade for photos.", "tip": "The classic silver Skywalker hilt with a blue blade is the read. He's no Jedi — hold it two-handed and a little unsure, that's the joke and the charm. Clip it to your belt when your hands are full.", "files": []}, "chain": {"name": "Rebel Legion Fit Check", "type": "SYSTEM · 08", "kind": "Craft", "hours": 1, "cost": 0, "priority": "MEDIUM", "description": "Not a physical part — a pass to check your jacket, henley and trousers against Rebel Legion reference photos. Rebel Legion is the good-guy costuming club; their Finn standards are your free accuracy checklist.", "tip": "Compare jacket colour, collar shape and henley tone side-by-side with their approved reference. Small colour corrections now save a rebuild later.", "files": []}, "codpiece": {"name": "Bloody Handprint (Trooper Option)", "type": "ALT · 06", "kind": "Makeup", "hours": 2, "cost": 12, "priority": "LOW", "description": "For builders going the FN-2187 stormtrooper armour route instead: the smeared red handprint dragged across the right side of the helmet — the mark left when a dying trooper grabs Finn. It's the single detail that makes trooper-armour Finn instead of a generic First Order trooper.", "tip": "Use a red weathering wash or acrylic, not glossy 'blood' — a dull, dragged, fingers-splayed smear reads far better than a bright splatter. Practice the drag on scrap first.", "files": []}, "cape": {"name": "Resistance Nod (Optional)", "type": "OUTER · 07", "kind": "Buy/Sew", "hours": 1, "cost": 5, "priority": "LOW", "description": "An optional small Resistance touch — a subtle patch, pin or the muted layered scarf sometimes seen in later looks. Keeps the costume unmistakably good-guy without cluttering the clean jacket silhouette.", "tip": "Less is more. One small Resistance pin or insignia beats covering the jacket in patches — Finn's look is defined by restraint, not gear.", "files": []}}, "weeks": [{"label": "Week 4", "task": "Choose your look (jacket or trooper armour — this guide is jacket). Thrift or order the tan/brown leather jacket, grey-blue henley, trousers, boots and saber."}, {"label": "Week 3", "task": "First full fit. Check jacket colour and collar against Rebel Legion refs. Push sleeves up, layer the henley, dial in the trouser break at the boot."}, {"label": "Week 2", "task": "Weather the jacket and boots — sand the collar and elbows, work in a little polish, scuff the toes. Fit the saber hilt and belt clip."}, {"label": "Week 1", "task": "Trim the hair short and matte, do a dress rehearsal, walk the house for an hour, pack a stain pen and safety pins — then game day."}], "files": [{"name": "Finn / FN-2187 costume reference", "designer": "Etsy / eBay", "url": "https://www.etsy.com/search?q=finn%20star%20wars%20cosplay%20jacket"}, {"name": "Skywalker blue lightsaber hilt STL", "designer": "Thingiverse", "url": "https://www.thingiverse.com/search?q=anakin+skywalker+lightsaber+hilt"}, {"name": "FN-2187 stormtrooper helmet 3D model (trooper option)", "designer": "Cults3D", "url": "https://cults3d.com/en/search?q=first+order+stormtrooper+helmet"}, {"name": "Rebel Legion Resistance standards", "designer": "Rebel Legion", "url": "https://rebellegion.com/"}], "checklist": {"print": [{"name": "Skywalker saber hilt", "detail": "Optional if buying a hilt instead of printing."}, {"name": "Saber belt clip / D-ring", "detail": "Hangs the hilt at the hip, hands free."}, {"name": "FN-2187 helmet (trooper option only)", "detail": "Skip entirely for the jacket build."}], "buy": [{"name": "Tan/brown leather jacket", "detail": "Poe's jacket — the whole build. Buy worn, or distress it."}, {"name": "Grey-blue henley", "detail": "Faded slate, waffle texture, sleeves pushed up."}, {"name": "Dark trousers + belt", "detail": "Charcoal/brown, tapered, simple leather belt."}, {"name": "Worn brown/black boots", "detail": "Scuffed, laced, comfortable for all-day."}, {"name": "Blue lightsaber", "detail": "Skywalker hilt, blue blade — grabbed, not owned."}, {"name": "Shoe polish + fine sandpaper", "detail": "For weathering the jacket and boots."}, {"name": "Fingerless gloves (optional)", "detail": "Scuffed brown — only if your reference has them."}, {"name": "Red weathering paint (trooper option)", "detail": "For the bloody handprint on the helmet."}]}, "chapters": [{"num": "01", "title": "Mission Brief", "body": "<p class='lead'>This builds <span class='accent'>Finn</span> — FN-2187, the First Order stormtrooper who refused to fire, defected, and threw in with the Resistance across the sequel trilogy.</p><p>Finn is one of the friendliest builds on the whole roster, because his hero look is a <span class='accent'>closet cosplay</span>: a tan leather jacket, a grey-blue henley, dark trousers, boots. No armour to print, no helmet to vacuum-form, no wig. If you've never made a costume before — or you want a great-looking build in a weekend — start here.</p><div class='reader-callout'><div class='label'>▌ WHY FINN IS A GREAT FIRST BUILD</div><p>Nearly everything can be thrifted or bought off the rack. The only optional print is the saber hilt, and even that has a buy option. You can land a convincing Finn for the price of a charity-shop jacket, a henley and a blue saber.</p></div>"}, {"num": "02", "title": "Pick Your Look", "body": "<p class='lead'>One character, two completely different builds. Choose before you spend a cent.</p><ul><li><b>The jacket (recommended)</b> — Finn in Poe's tan/brown leather jacket over a grey-blue henley. Beginner-friendly, instantly recognisable, comfortable to wear all day. This guide is built around this look.</li><li><b>FN-2187 stormtrooper armour</b> — the full white First Order shell with the <span class='accent'>bloody handprint</span> smeared on the helmet. Screen-accurate and dramatic, but it's a major armour build (weeks of printing, sanding and assembly) closer to the Trooper guide in scope.</li></ul><div class='reader-callout'><div class='label'>▌ FIRST-TIMER PICK</div><p>Build the jacket. It's the look most people recognise as Finn, it costs a fraction of the armour, and you can add the trooper build later once you've got a con or two under your belt.</p></div>"}, {"num": "03", "title": "The Jacket Is Everything", "body": "<p class='lead'>Get one thing right and you've got Finn: the jacket. Get it wrong and no amount of accessories saves it.</p><p>Finn borrows Poe's <span class='accent'>tan-to-brown leather flight jacket</span> — quilted shoulders, a worn collar, soft and lived-in. The colour sits between tan and warm brown, never black. Thrift a real leather jacket if you can; a good matte faux works, but avoid anything stiff or shiny.</p><h3>Weather it before you wear it</h3><ul><li>Sand the collar, cuffs and elbows lightly with fine sandpaper.</li><li>Rub a little brown shoe polish into the seams and high-wear spots, then buff it back.</li><li>Push the sleeves up so they bunch — Finn is never buttoned-up and tidy.</li></ul><div class='reader-callout'><div class='label'>▌ THE #1 TELL</div><p>A brand-new, glossy jacket. Finn just fought his way off a Star Destroyer and crash-landed on Jakku — the leather should look like it. Five minutes of weathering beats any amount of extra gear.</p></div>"}, {"num": "04", "title": "The Layers Underneath", "body": "<p class='lead'>The jacket names the look, but the layers underneath are what people read once you're up close.</p><ul><li><b>Henley:</b> a grey / blue-grey long-sleeve, faded slate, waffle texture. Sleeves pushed up under the jacket cuffs.</li><li><b>Trousers:</b> dark and tapered — charcoal, brown or faded black — tucked lightly at the boot.</li><li><b>Boots:</b> scuffed brown or black lace-ups, comfortable enough for a full con day.</li></ul><p>Keep the palette <span class='accent'>earthy and muted</span>. Nothing here should shout — Finn dresses like someone who grabbed what fit and kept moving.</p><div class='reader-callout'><div class='label'>▌ ONE SHADE OFF</div><p>If you add a peeking undershirt collar, make it a shade lighter or darker than the henley so the layers read as separate pieces, not one flat block of fabric.</p></div>"}, {"num": "05", "title": "The Blue Saber", "body": "<p class='lead'>Finn grabs the Skywalker lightsaber and swings it at Kylo Ren — no training, no finesse, all heart. That prop is the detail that sells the fight.</p><p>The <span class='accent'>silver Skywalker/Anakin hilt with a blue blade</span> is the read. Buy a hilt or print one, and add a lit or removable blade for hero shots. He's no Jedi, and that's the charm — hold it two-handed and a little unsure.</p><ul><li>Blue blade, classic ridged silver hilt — not a fancy custom saber.</li><li>A belt clip or D-ring frees your hands between photos.</li><li>Optional entirely — Finn without a saber still reads as Finn from the jacket alone.</li></ul><div class='reader-callout'><div class='label'>▌ PLAY THE MOMENT</div><p>For photos, plant your feet and raise the saber like you're bracing for a fight you might lose. That nervous-but-committed stance is pure Finn: 'We'll figure it out, we'll use the Force!'</p></div>"}, {"num": "06", "title": "Trooper Option: The Handprint", "body": "<p class='lead'>Going the harder route? The FN-2187 stormtrooper armour is a full white First Order build — and one detail makes it unmistakably <span class='accent'>Finn</span>, not a generic trooper.</p><p>When a dying comrade grabs him on the battlefield, he's left with a <span class='accent'>red handprint smeared across the right side of his helmet</span>. That mark is the whole story of his defection in one image.</p><ul><li>Build the standard First Order stormtrooper armour (a major print-and-sand project — see the Trooper guide for scope).</li><li>Add the handprint with a dull red weathering wash or acrylic — a dragged, fingers-splayed smear, never glossy 'blood'.</li><li>Practise the drag on scrap first; you get one clean shot on the helmet.</li></ul><div class='reader-callout'><div class='label'>▌ SCOPE WARNING</div><p>Trooper-armour Finn is weeks of work and a much bigger budget than the jacket. If it's your first build, do the jacket first — the handprint waits.</p></div>"}, {"num": "07", "title": "Game Day", "body": "<p class='lead'>Jacket weathered, henley layered, saber clipped — go be the trooper who chose better.</p><h3>The final pass</h3><ul><li>Trim the hair short and matte — no product shine.</li><li>Check jacket colour and collar against <span class='accent'>Rebel Legion</span> Finn reference photos; they're the good-guy costuming club and their standards are your free accuracy checklist.</li><li>Pack a stain pen and safety pins — leather scuffs, seams snag.</li><li>Walk the house for an hour first; comfortable boots make or break a con day.</li></ul><div class='reader-callout'><div class='label'>▌ STAY IN CHARACTER</div><p>Finn is brave, loyal, a little in over his head, and completely genuine. When someone asks who you are, grin and give them the line: 'That's not what I'm about.' The jacket does the rest.</p></div><div class=\"reader-callout\"><div class=\"label\">● ●  MORE GAME DAY LINES</div><ul><li>&ldquo;I'm not Resistance. I'm not a hero. I'm a stormtrooper.&rdquo; <i>&mdash; quiet, honest — the confession moment</i></li><li>&ldquo;We'll figure it out. We'll use the Force!&rdquo; <i>&mdash; big confident grin, absolutely winging it</i></li><li>&ldquo;Stay calm. Stay calm.&rdquo; <i>&mdash; then answer yourself: 'I am calm.' — 'I was talking to myself.'</i></li></ul></div><div class=\"reader-callout\"><div class=\"label\">😄 FOR LAUGHS — KID EDITION</div><ul><li>I used to work for the First Order. Now I work for recess.</li><li>FN-2187 reporting for snack duty!</li><li>Stay calm, stay calm. ...I was talking to my homework.</li></ul></div>"}, {"num": "08", "title": "Saber Craft", "body": "<p class=\"lead\">The blade is half the costume — fight like the character. <span class=\"accent\">Untrained</span>, wielded single borrowed.</p><div class=\"reader-callout\"><div class=\"label\">▌ STYLE · UNTRAINED</div><p>No form — a First Order soldier's melee-baton training poured into a weapon he'd never held before. Big committed two-handed swings, guts over technique; reads closest to raw Form I Shii-Cho fundamentals, the wide sweeping basics every duelist starts from. No form at all is the point — a stormtrooper's courage swinging a hero's borrowed weapon and refusing to run.</p></div><div class=\"reader-table\"><div class=\"reader-table-row\"><span class=\"col-key\">BLADE</span><span class=\"col-val\"><span style=\"color:#2e79f0\">⬤</span> Blue — borrowed Skywalker saber</span></div><div class=\"reader-table-row\"><span class=\"col-key\">WIELD</span><span class=\"col-val\">single borrowed</span></div></div><h3>Drill it</h3><p>Baton basics: one big two-handed block held high, one step back, reset to guard — ten slow reps. Keep the blade between you and the target instead of winding up wide.</p><div class=\"reader-callout\"><div class=\"label\">⚠ DUEL SAFELY</div><p>Duel-grade polycarbonate blades only, never thin display tubes. Agree intensity before you start, no strikes to head or hands, and staff or dual spins need a full 3m of clear space.</p></div>"}]};

/* ===== Vader chapter: The Voice (inserted after Game Day) ===== */
window.VADER_CHAPTERS.splice(8, 0, {
  num: "09",
  title: "The Voice",
  body: `
    <p class="lead">The suit makes you <span class="accent">look</span> like Vader. The voice makes people <span class="accent">believe</span> it. Three pillars: <b>LOW. SLOW. CALM.</b></p>

    <h3>1 · Go low — from the chest</h3>
    <p>Yawn once. Feel where your voice sits after the yawn — that relaxed, deep place is <b>chest voice</b>. Hum down to your lowest <i>comfortable</i> note and speak from there. Do not growl and do not rasp your throat: Vader is not angry gravel, he is a deep, calm engine.</p>

    <h3>2 · Go slow — pauses are power</h3>
    <p>Vader never hurries. Say the sentence… then <b>stop</b>… then say the next part. Every statement ends flat and final, like a door closing. If you think you are speaking too slowly, you are almost slow enough.</p>

    <h3>3 · The breath</h3>
    <p>The famous mechanical breath is two sounds: a slow pull <b>"kohh"</b> (in) and a soft release <b>"purr"</b> (out), made through a half-closed throat — or through a cupped fist over your mouth. The rule: <b>breathe between lines, never while talking.</b> Line… breath… line. That rhythm IS the character.</p>

    <div class="reader-callout">
      <div class="label">● ●  PRACTICE LINES</div>
      <ul>
        <li>"I find your lack of faith disturbing." — slow, flat, one pause before <i>disturbing</i>.</li>
        <li>"The Force is strong with this one." — calm, almost curious.</li>
        <li>"You have failed me for the last time." — quieter is scarier. Never shout.</li>
      </ul>
    </div>

    <h3>Resonance &amp; gear</h3>
    <p>Speaking inside the helmet adds natural echo — for practice without it, cup both hands (or a paper cup) over your mouth. A cheap toy <b>voice-changer</b> (~€10–20) clipped in the chest adds the metallic edge; convention Vaders run a small <b>mic + mini-amp kit</b> hidden in the chest box. Watch a real tutorial: <b>youtube.com/watch?v=taT_ySQWvlk</b> ("How To Voice Darth Vader", JD Cornwell). Or go full lazy-Sith: a phone in the chest playing a <b>12-hour breathing loop</b> — the suit breathes all day, you save your lungs for the lines. <b>⚠ Throat care:</b> the depth comes from the <b>chest</b>, never a squeezed throat — if it hurts, stop, sip water, go a little higher.</p>
  `
});
window.VADER_CHAPTERS.forEach(function(c, i){ c.num = (i + 1 < 10 ? "0" : "") + (i + 1); });

/* ===== Saber Craft chapters (vader + anakin) ===== */
window.VADER_CHAPTERS.push({ num: "XX", title: "Saber Craft", body: `<p class="lead">The blade is half the costume — fight like the character. <span class="accent">Shien/Djem So</span>, wielded single.</p><div class="reader-callout"><div class="label">▌ FORM V · SHIEN/DJEM SO — “The Way of the Krayt Dragon”</div><p>Pure dominance — block the strike, then crush the striker. Heavy one-handed and overhead blows delivered from a near-stationary stance; the armor takes the hit, the counter ends the fight. Djem So suits a man in heavy armor who never needs to run: stand, absorb, answer twice as hard.</p></div><div class="reader-table"><div class="reader-table-row"><span class="col-key">BLADE</span><span class="col-val"><span style="color:#d42b2b">⬤</span> Red</span></div><div class="reader-table-row"><span class="col-key">WIELD</span><span class="col-val">single</span></div></div><h3>Drill it</h3><p>Heavy-strike control: raise the saber overhead, hold a two-second pause of total stillness, then drop it in one straight line to a dead stop at chest height — ten reps each side, power from the stillness, not the swing.</p><div class="reader-callout"><div class="label">⚠ DUEL SAFELY</div><p>Duel-grade polycarbonate blades only, never thin display tubes. Agree intensity before you start, no strikes to head or hands, and staff or dual spins need a full 3m of clear space.</p></div>` });
window.VADER_CHAPTERS.forEach(function(c,i){ c.num=(i+1<10?"0":"")+(i+1); });
window.ANAKIN_CHAPTERS.push({ num: "XX", title: "Saber Craft", body: `<p class="lead">The blade is half the costume — fight like the character. <span class="accent">Shien/Djem So</span>, wielded single.</p><div class="reader-callout"><div class="label">▌ FORM V · SHIEN/DJEM SO — “The Way of the Krayt Dragon”</div><p>Aggression with a rulebook — every block is the first half of a counterattack. Strong deflections that flow instantly into powerful cuts, always pressing forward, never conceding tempo. Djem So is the form of someone who believes the best defense is winning — which is Anakin in one sentence.</p></div><div class="reader-table"><div class="reader-table-row"><span class="col-key">BLADE</span><span class="col-val"><span style="color:#2e79f0">⬤</span> Blue</span></div><div class="reader-table-row"><span class="col-key">WIELD</span><span class="col-val">single</span></div></div><h3>Drill it</h3><p>Counter-cut drill: block an imaginary diagonal strike, then immediately cut back along the exact same line as one single beat — block-and-answer, not block-then-answer. Ten reps per side.</p><div class="reader-callout"><div class="label">⚠ DUEL SAFELY</div><p>Duel-grade polycarbonate blades only, never thin display tubes. Agree intensity before you start, no strikes to head or hands, and staff or dual spins need a full 3m of clear space.</p></div>` });
window.ANAKIN_CHAPTERS.forEach(function(c,i){ c.num=(i+1<10?"0":"")+(i+1); });

