window.VADER_CHAPTERS.forEach(function(ch){ if(ch.title==="Paint Protocol" && ch.body.indexOf("<div class=\"reader-callout\"><div class=\"")<0) ch.body += `<div class="reader-callout"><div class="label">SEMI-GLOSS · DOME VS MASK</div><p>Vader's "black" is not pure black — it reads slightly blue-black with semi-gloss reflectance; pure matte eats the costume on camera. The helmet is semi-gloss with the dome glossier than the mask: polish the dome with carnauba car wax for the final wet-look shine. Only have matte and gloss varnish? A 50/50 mix gives you satin.</p></div>`; });
window.VADER_CHAPTERS.forEach(function(ch){ if(ch.title==="Game Day" && ch.body.indexOf("<div class=\"reader-callout\"><div class=\"")<0) ch.body += `<div class="reader-callout"><div class="label">CAPE MOBILITY · FROM REHEARSAL</div><ul><li>Sit: sweep the cape forward with both hands first — never sit on it.</li><li>Stairs: gather cape in the non-saber hand, lift 10cm — going down it catches heels.</li><li>Doorways: turn slightly sideways, lead with one shoulder — frames eat shoulder armor.</li><li>Cars: chest plate first, cape last — or remove the chest plate for transit.</li></ul></div>`; });
window.VADER_CHAPTERS.forEach(function(ch){ if(ch.title==="Variant Reference" && ch.body.indexOf("<div class=\"reader-callout\"><div class=\"")<0) ch.body += `<div class="reader-callout"><div class="label">BEGINNER RECOMMENDATION · BUILD ESB</div><p>ESB is the most documented, most referenced era, with the most files available. Once you've built ESB you can shift to other eras with helmet + chest panel swaps. Don't start with ANH or Rogue One unless you have a strong reason.</p></div>`; });
window.ANAKIN_CHAPTERS.forEach(function(ch){ if(ch.title==="Variant Reference" && ch.body.indexOf("<h3>Advanced \u00b7 Knightfall &amp; the Worl")<0) ch.body += `<h3>Advanced · Knightfall &amp; the World Between Worlds</h3><p>Two advanced looks for when your base Anakin is done. <strong>Knightfall</strong> — the Episode III robes with yellow Sith eyes and a cold, blank stare (no scars yet — it's before the burns). A ring of yellow-and-red eyeshadow reads as "Sith eyes" safely; contacts only with adult + eye-care professional help. <strong>The Cracked Helmet</strong> — half a Vader helmet with a jagged, foam-built broken edge over pale scarred makeup and one yellow eye. Half hero, half machine — "there's still good in him."</p>`; });
window.ANAKIN_CHAPTERS.forEach(function(ch){ if(ch.title==="Procurement Roster" && ch.body.indexOf("<div class=\"reader-callout\"><div class=\"")<0) ch.body += `<div class="reader-callout"><div class="label">FREE ARMOUR FILES · CLONE WARS &amp; AHSOKA</div><p>Anakin's Pauldron by Bugman_140 (Printables 68631) is a free STL of the exact left-shoulder armour — child + adult sizes, with slots for two 10×10×5&nbsp;mm magnets so it snaps onto your sleeve. Armatus Designs' free Jedi Cosplay Gauntlets (Printables 1403127) are magnetized too, in several sizes. Magnets beat glue: the armour snaps on, comes off for the car, and survives bumps.</p></div>`; });
window.ANAKIN_CHAPTERS.forEach(function(ch){ if(ch.title==="Robes & Tunic" && ch.body.indexOf("<div class=\"reader-callout\"><div class=\"")<0) ch.body += `<div class="reader-callout"><div class="label">KID-GROWS-INTO-IT TIP</div><p>Buy the tunic and robe a little big and hem them now. As you grow, let the hem down. Brown and navy hide stitching well, so adjustments are easy to hide.</p></div>`; });


// FINAL5 restoration — anakin chapters (2026-07-12)
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="The Jedi Code";}))return;var i=A.findIndex(function(c){return c.title==="Mission Brief";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"The Jedi Code",body:"<p class=\"lead\">Every Jedi learns the Code — five lines that keep you calm and centered. Anakin wrestled with it his whole life (that's his whole story), but a Jedi-in-training knows it by heart. Read it before you suit up.</p><div class=\"reader-callout\"><div class=\"label\">THE JEDI CODE</div><p>There is no emotion, there is peace.<br>There is no ignorance, there is knowledge.<br>There is no passion, there is serenity.<br>There is no chaos, there is harmony.<br>There is no death, there is the Force.</p></div><h3>The Builder's Code (for the Workshop)</h3><ul><li>There is no panic, there is a checklist.</li><li>There is no guessing, there is a test print.</li><li>There is no glue where there could be magnets.</li><li>There is no rushing, there is the 90-minute test wear.</li><li>There is no red blade — there is blue.</li></ul><p>One code for the con, one for the workbench. Recite accordingly.</p>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="Knightfall & the World Between Worlds";}))return;var i=A.findIndex(function(c){return c.title==="Variant Reference";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"Knightfall & the World Between Worlds",body:"<p class=\"lead\">The advanced Anakin — the moment he stops being only Anakin and starts becoming Vader. Two related looks, both about the man and the monster as one. They take more makeup and prop work than the three main looks, so try them once you've built a base Anakin you're happy with.</p><h3>Knightfall — The Jedi Who Fell</h3><p>Anakin in his Jedi robes during the march on the Jedi Temple. Start from the Episode III look you already know — brown robes, the single glove, the blue saber — and change just two things: the eyes and the attitude. He still looks like a Jedi; the change is in the eyes and the cold expression. No scars yet — Knightfall is before the burns. Hood up for the dramatic entrance, then back to show the eyes.</p><div class=\"reader-callout\"><div class=\"label\">THE YELLOW SITH EYES — WITH CARE</div>The fall shows in the eyes: a ring of yellow-orange with a red rim. Best for kids: skip contacts — a ring of yellow and red eyeshadow with a little dark shading reads as \"Sith eyes\" in photos. Costume contacts only with an adult and an eye-care professional who fits them to you. Never share lenses, never sleep in them, never use cheap unfitted ones.</div><h3>The Cracked Helmet — World Between Worlds</h3><p>The showpiece: one side Anakin's face, the other Vader's shattered helmet, as if the mask broke to reveal the man inside. Print just the left half of a Vader helmet, or build the broken edge from craft foam so it looks shattered, not neatly sliced — jagged, with a little silver on the rim to read as bent metal. Your own face shows through the open side: pale base blended at the helmet edge, scars built with skin-safe products only (stylised, not gruesome), and the one yellow eye. Patch-test every product on a small patch of skin 24 hours early — if it gets itchy or red, stop and wash it off. Check you can see on the helmet side (tinted mesh in the eye socket) and that nothing presses on your face.</p><div class=\"reader-callout\"><div class=\"label\">READ THE ROOM</div>This look is powerful and a little eerie — perfect for older fans and photos, but it can spook little kids. If a small one looks unsure, turn the Anakin side toward them, smile, and say something kind. The whole idea is \"there's still good in him\" — let that show.</div>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="The Armor (3D Printed)";}))return;var i=A.findIndex(function(c){return c.title==="Robes & Tunic";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"The Armor (3D Printed)",body:"<p class=\"lead\">Episode III skips this whole section — it's all cloth. The Clone Wars and Ahsoka looks add armor: a pauldron (left shoulder), gauntlets (forearms), and — for Ahsoka — a chest plate. Anakin was a Jedi General who led clone troopers in the Clone Wars — hence the armor. The shoulder file is FREE.</p><div class=\"reader-callout\"><div class=\"label\">THE FREE PAULDRON — START HERE</div>Anakin's Pauldron by Bugman_140 on Printables (model 68631) is a free STL of the exact left-shoulder armor. It comes in a small (child) and large (adult) size — print the small one. It has slots for two 10×10×5 mm magnets so it snaps onto your sleeve. The pauldron is small — print it first as your test piece to prove your settings before the chest plate.</div><h3>The Pauldron</h3><p>One curved plate over the LEFT shoulder. Print the child size, finish it (see Finishing the Armor), and attach with two magnets — one inside the tunic shoulder, one in the armor — so it snaps on and off, comes off for the car, and survives bumps. Magnets beat glue.</p><h3>The Gauntlets</h3><p>Forearm armor on both arms. There's a FREE file — Armatus Designs' \"Jedi Cosplay Gauntlets (Clone Wars)\" on Printables — magnetized, with several sizes and a split version for small printers. Finish them the same dark grey as the pauldron.</p><h3>The Chest Plate (Ahsoka only)</h3><p>The live-action flashback adds a chest/shoulder plate over the tunic. It's a bigger print — do it last. Clone Wars (animated) skips it. Armor snaps on last, over the belted tunic; Clone Wars and Ahsoka Anakin often fight with the robe off so the armor shows — bring it for a dramatic entrance or leave it off.</p><div class=\"reader-callout\"><div class=\"label\">DON'T WANT TO PRINT IT?</div>Ready-made kits exist — search \"Anakin Clone Wars / Ahsoka shoulder & chest armor kit\" with magnetic openings on Etsy and cosplay sites. Costs more than printing but zero sanding.</div>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="Finishing the Armor";}))return;var i=A.findIndex(function(c){return c.title==="The Armor (3D Printed)";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"Finishing the Armor",body:"<p class=\"lead\">Episode III builders can skip this — no armor to finish. A fresh print has visible layer lines and feels rough. \"Finishing\" turns a plastic print into screen armor — the same routine the Vader manual uses. If you've never done it, here is every step and exactly what to buy.</p><h3>What You'll Buy</h3><ul><li>Sandpaper — a multi-grit pack: 120 / 240 / 320 / 400 / 600.</li><li>Filler primer (grey rattle can) — Rust-Oleum or Tamiya; thick spray that fills tiny lines.</li><li>Spray paint, dark grey — the base colour of the armor.</li><li>Black acrylic (small pot) — for the \"dirty\" wash in the grooves.</li><li>Silver acrylic (small pot) — for scuffed-metal edges.</li><li>Spot filler / putty — only if a part printed in pieces.</li><li>Satin clear coat spray, a respirator/dust mask, painter's tape.</li></ul><p>Sanding = rubbing off printer ridges. Priming = a base spray that fills the last tiny lines and helps colour stick. A wash = watered-down dark paint that runs into grooves to make detail pop. Weathering = fake scuffs so the armor looks used, not new.</p><div class=\"reader-table\"><div class=\"reader-table-row\"><span class=\"col-key\">1 · Sand</span><span class=\"col-val\">120 grit, then 240, then 400 — each pass removes the last one's scratches.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">2 · Fill seams</span><span class=\"col-val\">Glue multi-part prints, fill the join with putty, cure overnight, sand flat.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">3 · Wipe clean</span><span class=\"col-val\">Damp cloth, then dry fully — no dust.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">4 · Filler primer</span><span class=\"col-val\">Spray a coat, let dry, wet-sand 320 grit (a little water, in circles). Repeat once.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">5 · Base coat</span><span class=\"col-val\">Dark grey spray, 2 thin coats, ~20 min apart.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">6 · Wash</span><span class=\"col-val\">Water down black acrylic, brush into grooves, wipe the flats.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">7 · Scuffs</span><span class=\"col-val\">Dry-brush a little silver on edges for battle-worn metal.</span></div><div class=\"reader-table-row\"><span class=\"col-key\">8 · Clear coat</span><span class=\"col-val\">One light satin coat to seal. Done.</span></div></div><div class=\"reader-callout\"><div class=\"label\">SPRAY SAFETY</div>Spray outside or in an open garage only — never indoors. Wear the mask, keep away from flames. Sanding dust isn't good to breathe either, so mask up for that too. Under 18? Have an adult with you.</div>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="Manufacturing Files";}))return;var i=A.findIndex(function(c){return c.title==="Build Sequence";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"Manufacturing Files",body:"<p class=\"lead\">Every link in this manual, gathered for quick reference.</p><h3>Armor Files (Clone Wars & Ahsoka)</h3><ul><li>Anakin's Pauldron by Bugman_140 · FREE · printables.com/model/68631-anakins-pauldron (child + adult sizes, magnet slots)</li><li>Shoulder pad remix (with Jedi Order emblem) · thingiverse.com — search \"Anakin Clone Wars shoulder pad\"</li><li>Jedi Cosplay Gauntlets (Clone Wars) by Armatus Designs · FREE · printables.com/model/1403127-jedi-cosplay-gauntlets-clone-wars (magnetized, multiple sizes, split for small printers)</li><li>General Anakin Clone Wars / Ahsoka armor (full chest set) · pewpewcrafts · cults3d.com — search \"General Anakin clone wars armor\" (paid)</li><li>General Kenobi armor (same era, great assembly tutorial) · Galactic Armory · galacticarmory.net (paid)</li></ul><h3>Lightsaber Hilt Files (All Looks)</h3><ul><li>CaseStudyno8 — Anakin/Luke saber · thingiverse.com/thing:1538383</li><li>infinati — 8-piece easy-print saber · thingiverse.com/thing:321812 (small-printer + hot-glue friendly)</li><li>Interceptor neopixel-ready hilt · printables.com/model/89074</li></ul><p>Hilt spotting guide: metal look, Graflex-style emitter, black grips, two buttons (one silver, one copper), covertec wheel near the bottom.</p><h3>Standards & Shopping</h3><ul><li>Anakin Ep III standards — rebellegion.com/anakin-skywalker-episode-iii/</li><li>Generic Jedi standards — rebellegion.com/costume-standards/jedi/</li><li>Full set — AliExpress / eBay (search: Anakin cosplay costume)</li><li>Armor kit, no printing — etsy.com (search: Anakin Ahsoka armor kit)</li></ul><div class=\"reader-callout\"><div class=\"label\">SIZING THE ARMOR</div>Most cosplay armor is modeled for adults. The free pauldron has a child size built in — use it. For other files, scale to ~80–85% in your slicer and test-print a small section first.</div>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;if(A.some(function(c){return c.title==="Meeting Your Fans";}))return;var i=A.findIndex(function(c){return c.title==="Game Day";});A.splice(i<0?A.length-1:i+1,0,{num:'00',title:"Meeting Your Fans",body:"<p class=\"lead\">Half the magic of a costume is what you say when someone walks up. Here are in-character lines ready to go — gentle ones for little kids, and bigger ones for older fans and photos.</p><div class=\"reader-callout\"><div class=\"label\">GOLDEN RULE — READ THE ROOM</div>Heroes get mobbed by little fans — lean into it. Kneel to their height, keep it warm, and let them feel like part of the adventure.</div><h3>For Little Kids — Kind and Playful</h3><ul><li>\"I built droids when I was your age — you can build amazing things too!\"</li><li>\"Want to see a Jedi flip? Okay, I'll just imagine it for now.\"</li><li>\"Being scared is okay. Being brave anyway is the Jedi way.\"</li></ul><h3>Big and In-Character — Older Fans and Photos</h3><ul><li>\"This is where the fun begins.\"</li><li>\"I'm good at building things — and at winning.\"</li><li>\"I sense great things in your future.\"</li></ul><p>Universal tips for meeting young fans: kneel to their eye level, never break character to correct them, ask their name and make them the hero, and if a prop weapon is involved keep it lowered and pointed away. The goal is simple — every kid walks away thinking they just met the real one.</p><p>Posture for photos: Anakin is intense. Blue blade lit, slight scowl, blade held low and angled across the body. A billowing robe adds drama.</p>"});})();
(function(){var A=window.ANAKIN_CHAPTERS;var c=A.find(function(c){return c.title==="Variant Reference";});if(c&&c.body.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').toLowerCase().indexOf("upgrade path the blue saber, brown leather belt, tall boots,")<0)c.body+="<h3>Upgrade Path</h3><p>The blue saber, brown leather belt, tall boots, single right-hand glove and robe/tunic base are shared by all three looks — build Episode III first, then add printed armor later without starting over. Level up: print the pauldron + gauntlets and darken the tunic for Clone Wars; add the chest plate and swap to navy + maroon for Ahsoka.</p><div class=\"reader-callout\"><div class=\"label\">COLOUR CHEAT-SHEET</div>Ep III: deep brown tunic (cotton/linen, not shiny), cream under-tunic, mahogany trousers. Clone Wars: dark blue / near-black tunic, grey armor. Ahsoka: navy microsuede tunic over maroon under-layers, dark grey weathered armor. Brown belt & boots for all. Scar: clear in Ep III; faint or not yet in Clone Wars / early Ahsoka.</div>";})();
(function(){var A=window.ANAKIN_CHAPTERS;var c=A.find(function(c){return c.title==="Build Sequence";});if(c&&c.body.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').toLowerCase().indexOf("armor track (clone wars & ahsoka only) the armor track runs ")<0)c.body+="<h3>Armor Track (Clone Wars & Ahsoka Only)</h3><p>The armor track runs in parallel — start the prints day one so they run while you sort the cloth.</p><ul><li>A · Download & start prints: free pauldron (child size) + gauntlets (+ chest plate for Ahsoka).</li><li>B · Finish the armor: sand, prime, paint dark grey, weather, clear coat.</li><li>C · Add magnets to the pauldron, elastic to the gauntlets.</li><li>D · Snap the armor on last, over the belted tunic.</li></ul><p>Armored-look kit extras: spare magnets, a glue stick, and elastic. Pop the pauldron off between photos if you need a break — that's what the magnets are for.</p>";})();
