// FINAL5 surgical patch — anakin (2026-07-12)
(function(){var A=window.ANAKIN_CHAPTERS;var c=A.find(function(c){return c.title==="Mission Brief";});if(c&&c.body.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').toLowerCase().indexOf("this manual builds anakin skywalker \u2014 three differ")<0)c.body+="<p>This manual builds Anakin Skywalker — three different ways, in one book. All three looks share the same blue blade; they differ in colours and in how much armor you add. Pick one before you buy anything — it sets your colours, your hair, and how much printing you’ll do.</p><div class=\"reader-callout\"><div class=\"label\">WHICH CLUB?</div>Jedi costumes belong to the Rebel Legion — the heroes’ costuming club — not the 501st. Their Anakin standards are linked in Manufacturing Files.</div>";})();
(function(){var A=window.ANAKIN_CHAPTERS;var c=A.find(function(c){return c.title==="Robes & Tunic";});if(c&&c.body.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').toLowerCase().indexOf("the robe/cloak is optional \u2014 anakin often leaves i")<0)c.body+="<p>The robe/cloak is optional — Anakin often leaves it off in battle scenes, so don’t panic if it isn’t ready. If you wear it: hem it so it ends about 5 cm (2 inches) off the floor — long, but safe on stairs.</p>";})();
